import {
  DEFAULT_LAYOUT_OPTIONS, NodeSearchIndex, describeLinkGesture, helpLines, nodeBoxes, Emitter, ForceSimulation, Graph, buildGroupIndex, computeLayout, createConfig, geometry, mergeConfig,
  placeNewNodes, resolveEdgeStyle, resolveNodeStyle, resolveUrl,
} from '../core/index';
import type {
  SearchResult, ChangeKind, DeepPartial, Dimension, EdgeData, EdgeStyle, GraphData, GraphscapeConfig, LayoutName, LayoutOptions, NodeData, NodeStyle, Vec3,
} from '../core/index';
import { TextureCache, type TextImage } from './labels';
import { injectStyles } from './styles';

type Body = geometry.Body;

/** What the view needs from OrbitControls (2D, 3D orbit) and TrackballControls (3D free rotation). */
interface CamControls {
  enabled: boolean;
  target: THREE.Vector3;
  minDistance: number;
  maxDistance: number;
  update(): unknown;
}

export type Tool = 'select' | 'connect';

/** Result of one benchmark phase (see `view.runBenchmark`). */
export interface BenchPhase {
  frames: number;
  /** Display-limited: rendering is capped at the refresh rate. Look at the CPU times for the headroom. */
  fps: number;
  frameMsAvg: number;
  frameMsP95: number;
  frameMsMax: number;
  updateMsAvg: number;
  renderMsAvg: number;
}
export interface BenchmarkResult {
  /** Camera moves, nothing else changes (panning, zooming, orbiting). */
  camera: BenchPhase;
  /** Camera moves and all positions update every frame (a running layout, dragging many nodes). */
  updates: BenchPhase;
}

const NO_GROUP = '\u0000';
export type GizmoMode = 'translate' | 'rotate' | 'scale';
export interface Selection {
  nodes: string[];
  edges: string[];
}

export interface ViewEvents {
  nodeclick: { id: string; node: NodeData; originalEvent: PointerEvent };
  nodedblclick: { id: string; node: NodeData; originalEvent: MouseEvent };
  edgeclick: { id: string; edge: EdgeData; originalEvent: PointerEvent };
  /** `position` is the world position under the pointer (z = 0 in 2D). */
  backgroundclick: { position: Vec3; originalEvent: PointerEvent };
  backgrounddblclick: { position: Vec3; originalEvent: MouseEvent };
  selection: Selection;
  hover: { kind: 'node' | 'edge' | null; id: string | null };
  nodedragstart: { ids: string[] };
  nodedragend: { ids: string[] };
  /** Fired in the `connect` tool when a drag from one node is released over another (or the same) node. */
  connect: { source: string; target: string };
  /** Fired before a link is opened. Set `handled = true` to take over (or use `links.target: "event"`). */
  link: { url: string; resolved: string; kind: 'node' | 'edge'; id: string; handled: boolean };
  layoutstart: { name: LayoutName };
  layoutend: { name: LayoutName; completed: boolean };
  dimensionchange: { dimension: Dimension };
  fullscreenchange: { fullscreen: boolean };
  gizmomode: { mode: GizmoMode };
  /** Groups hidden through the legend or `setGroupVisible` (null stands for nodes without a group). */
  groupvisibility: { hidden: (string | null)[] };
  /** Fired by the search box and by `view.search()`. */
  search: { query: string; ids: string[]; tooShort: boolean };
}

interface Layer {
  key: string;
  body: THREE.InstancedMesh;
  outline: THREE.InstancedMesh;
}

interface NodeInfo {
  node: NodeData;
  style: NodeStyle;
  body: Body;
  layerKey: string | null;
  layer: Layer | null;
  slot: number;
  card?: TextImage;
  sprite?: THREE.Sprite;
  badge?: THREE.Sprite;
}

interface EdgeInfo {
  edge: EdgeData;
  style: EdgeStyle;
  weight: number;
  directed: boolean;
  index: number;
  count: number;
  flip: boolean;
  self: boolean;
  path: Vec3[];
  arrowSlot: number;
  tip?: { tip: Vec3; dir: Vec3 };
  bucketKey: string;
  sprite?: THREE.Sprite;
  img?: TextImage;
  badge?: THREE.Sprite;
}

interface Bucket {
  key: string;
  mesh: LineSegments2;
  edges: EdgeInfo[];
  dashed: boolean;
}

type Hit = { kind: 'node' | 'edge'; id: string } | { kind: null; id: null };

type Drag =
  | { type: 'nodes'; ids: string[]; primary: string; offsets: Map<string, Vec3>; starts: Map<string, Vec3>; anchor: Vec3; px: number; py: number; moved: boolean }
  | { type: 'connect'; from: string }
  | { type: 'box'; x0: number; y0: number };

const ORTHO_HEIGHT = 400;
const X_AXIS = new THREE.Vector3(1, 0, 0);
const Y_AXIS = new THREE.Vector3(0, 1, 0);
type Axis = 'x' | 'y' | 'z';
const AXIS_INDEX: Record<Axis, number> = { x: 0, y: 1, z: 2 };
const AXIS_COLOR: Record<Axis, string> = { x: '#e03131', y: '#2f9e44', z: '#1c7ed6' };
const IDENTITY_Q = new THREE.Quaternion();
const DRAG_THRESHOLD = 4;

/**
 * Interactive three.js graph view (2D orthographic or 3D perspective).
 * Create it with a container element that has a size, then `load()` a graph.
 */
export class GraphView {
  readonly events = new Emitter<ViewEvents>();
  config: GraphscapeConfig;

  private _graph: Graph;
  private userConfig: DeepPartial<GraphscapeConfig>;
  private container: HTMLElement;
  private root: HTMLElement;
  private canvas: HTMLCanvasElement;
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private persp: THREE.PerspectiveCamera;
  private ortho: THREE.OrthographicCamera;
  private camera: THREE.PerspectiveCamera | THREE.OrthographicCamera;
  private controls!: CamControls;
  private orbit: OrbitControls | null = null;
  private disposeControls: () => void = () => {};
  private pointerIsDown = false;
  private activeUntil = 0;
  private ambient = new THREE.AmbientLight(0xffffff, 1.8);
  private headlight = new THREE.DirectionalLight(0xffffff, 1.6);
  private tex: TextureCache;
  private width = 1;
  private height = 1;
  private ro: ResizeObserver | null = null;
  private raf = 0;
  private disposed = false;
  private unsubGraph: () => void = () => {};

  private nodeInfo = new Map<string, NodeInfo>();
  private edgeInfo = new Map<string, EdgeInfo>();
  private layers = new Map<string, Layer>();
  private buckets: Bucket[] = [];
  private arrowMesh: THREE.InstancedMesh | null = null;
  private geoms = new Map<string, THREE.BufferGeometry>();
  private colors = new Map<string, THREE.Color>();

  private selNodes = new Set<string>();
  private selEdges = new Set<string>();
  private hoverNode: string | null = null;
  private hoverEdge: string | null = null;
  private tool: Tool = 'select';

  private dirtyStructure = true;
  private dirtyPositions = false;
  private dirtyNodes = false;
  private dirtyEdges = false;
  private dirtyLabels = false;
  private pendingFit = true;
  private pendingLayout = false;

  private sim: ForceSimulation | null = null;
  private simResolve: (() => void) | null = null;
  private dragIds: string[] = [];

  private drag: Drag | null = null;
  private down: { x: number; y: number; hit: Hit; additive: boolean; wasSelected: boolean; moved: boolean; button: number } | null = null;
  private lastPointer = { x: 0, y: 0 };
  private hoverRaf = 0;
  private rubber: THREE.Line | null = null;
  private guide: THREE.Line | null = null;
  private axisKeys = new Set<Axis>();
  private appliedVars: string[] = [];

  private tooltipEl: HTMLDivElement;
  private boxEl: HTMLDivElement;
  private controlsEl: HTMLDivElement | null = null;
  private dimButton: HTMLButtonElement | null = null;
  private fsButton: HTMLButtonElement | null = null;
  private hiddenGroups = new Set<string>();
  private legendEl: HTMLDivElement | null = null;
  private legendRows: { key: string; ids: string[]; row: HTMLElement }[] = [];
  private legendCollapsed = false;
  private statsEl: HTMLDivElement | null = null;
  private statsText: HTMLElement | null = null;
  private statsTimer = 0;
  private benchText = '';
  private benchmarking = false;
  private gpuName: string | null = null;
  private perf = { n: 0, update: new Float32Array(120), render: new Float32Array(120), stamps: [] as number[], rebuildMs: 0, positionsMs: 0, stepMs: 0 };
  private searchIndex: NodeSearchIndex | null = null;
  private searchEl: HTMLDivElement | null = null;
  private searchInput: HTMLInputElement | null = null;
  private searchCount: HTMLSpanElement | null = null;
  private searchText = '';
  private searchActive = false;
  private helpEl: HTMLDivElement | null = null;
  private helpButton: HTMLButtonElement | null = null;
  private pointerInside = false;
  private chipEl: HTMLButtonElement;
  private chipTarget: { kind: 'node' | 'edge'; id: string } | null = null;

  // transform gizmo: TransformControls attached to an invisible pivot at the center of the selection
  private tc: TransformControls | null = null;
  private tcHelper: THREE.Object3D | null = null;
  private pivot = new THREE.Object3D();
  private gizmoMode: GizmoMode = 'translate';
  private gizmoDragging = false;
  private gizmoStart: { pivot: THREE.Vector3; nodes: Map<string, Vec3> } | null = null;
  private snapHeld = false;
  private panelEl: HTMLDivElement | null = null;

  private tmpM = new THREE.Matrix4();
  private tmpV = new THREE.Vector3();
  private tmpV2 = new THREE.Vector3();
  private tmpQ = new THREE.Quaternion();
  private tmpS = new THREE.Vector3();
  private raycaster = new THREE.Raycaster();
  private plane = new THREE.Plane();

  constructor(container: HTMLElement, config: DeepPartial<GraphscapeConfig> = {}, graph?: Graph | Partial<GraphData>) {
    this.container = container;
    this.userConfig = config;
    this.config = createConfig(config);
    this._graph = graph instanceof Graph ? graph : new Graph(graph);
    if (this.config.ui.injectStyles) injectStyles();
    container.classList.add('gs-container');
    this.root = document.createElement('div');
    this.root.className = 'gs-root';
    container.appendChild(this.root);

    this.renderer = new THREE.WebGLRenderer({ antialias: this.config.render.antialias, alpha: true });
    this.renderer.setClearColor(0x000000, 0);
    this.canvas = this.renderer.domElement;
    this.root.appendChild(this.canvas);
    this.tex = new TextureCache(this.config.label.resolution);

    this.persp = new THREE.PerspectiveCamera(this.config.camera.fov, 1, 1, 100000);
    this.ortho = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10000);
    this.camera = this.config.dimension === '3d' ? this.persp : this.ortho;
    this.scene.add(this.ambient, this.headlight, this.headlight.target, this.pivot);

    this.tooltipEl = document.createElement('div');
    this.tooltipEl.className = 'gs-tooltip gs-ui';
    this.tooltipEl.hidden = true;
    this.boxEl = document.createElement('div');
    this.boxEl.className = 'gs-box';
    this.boxEl.hidden = true;
    this.chipEl = document.createElement('button');
    this.chipEl.type = 'button';
    this.chipEl.className = 'gs-chip gs-ui';
    this.chipEl.hidden = true;
    this.chipEl.addEventListener('click', () => {
      if (this.chipTarget) this.openLink(this.chipTarget.kind, this.chipTarget.id);
    });
    this.root.append(this.tooltipEl, this.boxEl, this.chipEl);

    this.setupCamera();
    this.buildControls();
    this.buildSearch();
    this.buildStats();
    this.applyAppearance();
    this.events.on('selection', () => this.updateLegendSelection());

    this.root.addEventListener('pointerdown', this.onPointerDown, true);
    this.root.addEventListener('pointermove', this.onPointerMove);
    this.root.addEventListener('pointerup', this.onPointerUp);
    this.root.addEventListener('pointercancel', this.onPointerUp);
    this.root.addEventListener('pointerleave', this.onPointerLeave);
    this.root.addEventListener('pointerenter', () => { this.pointerInside = true; });
    this.root.addEventListener('dblclick', this.onDblClick);
    this.root.addEventListener('wheel', this.onWheel, { passive: true });
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
    window.addEventListener('blur', this.onBlur);
    document.addEventListener('fullscreenchange', this.onFullscreenChange);
    if (typeof ResizeObserver !== 'undefined') {
      this.ro = new ResizeObserver(() => this.resize());
      this.ro.observe(container);
    }
    this.subscribe();
    this.resize();
    this.afterLoad();
  }

  // ------------------------------------------------------------------ public API

  get graph(): Graph {
    return this._graph;
  }

  on<K extends keyof ViewEvents>(type: K, fn: (payload: ViewEvents[K]) => void): () => void {
    return this.events.on(type, fn);
  }

  /** Replaces the content with a graph (or graph data). The view adopts `meta.dimension` when present. */
  load(data: Graph | Partial<GraphData>): void {
    this.stopLayout();
    this.unsubGraph();
    if (data instanceof Graph) this._graph = data;
    else this._graph.load(data, false);
    this.subscribe();
    this.selNodes.clear();
    this.selEdges.clear();
    this.hoverNode = this.hoverEdge = null;
    const dim = this._graph.meta.dimension;
    if (dim && dim !== this.config.dimension) this.setDimension(dim);
    this.afterLoad();
  }

  /** Forces a full rebuild (e.g. after changing node data without going through the Graph API). */
  refresh(): void {
    this.dirtyStructure = true;
    this.requestRender();
  }

  getConfig(): GraphscapeConfig {
    return this.config;
  }

  /** The partial config that was passed in / patched so far (what you would save as a config file). */
  getUserConfig(): DeepPartial<GraphscapeConfig> {
    return this.userConfig;
  }

  /** Deep-merges a patch into the user config and re-applies everything (theme, colors, labels, buttons, ...). */
  setConfig(patch: DeepPartial<GraphscapeConfig>): void {
    const { dimension, ...rest } = patch;
    this.applyUserConfig(mergeConfig(this.userConfig, rest));
    if (dimension !== undefined) this.setDimension(dimension);
  }

  /**
   * Replaces the whole user config (instead of merging into it): keys that are missing fall back to the
   * theme and the defaults again. The current dimension is kept unless the new config names one.
   */
  setUserConfig(config: DeepPartial<GraphscapeConfig>): void {
    const { dimension, ...rest } = config;
    this.applyUserConfig({ ...rest, dimension: this.config.dimension });
    if (dimension !== undefined) this.setDimension(dimension);
  }

  private applyUserConfig(next: DeepPartial<GraphscapeConfig>): void {
    const prevRotation = this.config.camera.rotation;
    this.userConfig = next;
    this.config = createConfig(this.userConfig);
    this.tex.resolution = this.config.label.resolution;
    this.tex.clear();
    this.persp.fov = this.config.camera.fov;
    this.persp.updateProjectionMatrix();
    if (this.config.dimension === '3d' && this.config.camera.rotation !== prevRotation) this.setupCamera(true);
    if (this.orbit) this.orbit.enableDamping = this.config.camera.damping;
    this.applyControlLimits();
    this.applyAppearance();
    this.buildControls();
    this.buildSearch();
    this.buildStats();
    this.closeHelp();
    this.setupGizmo();
    this.dirtyStructure = true;
    this.requestRender();
  }

  getDimension(): Dimension {
    return this.config.dimension;
  }

  setDimension(dimension: Dimension): void {
    if (dimension === this.config.dimension) return;
    this.stopLayout();
    this.userConfig = mergeConfig(this.userConfig, { dimension });
    this.config = createConfig(this.userConfig);
    this.camera = dimension === '3d' ? this.persp : this.ortho;
    this.setupCamera();
    this.resize();
    this.dirtyStructure = true;
    this.pendingFit = this.config.camera.autoFit;
    if (this.dimButton) this.dimButton.textContent = dimension === '2d' ? '3D' : '2D';
    this.events.emit('dimensionchange', { dimension });
    this.requestRender();
  }

  /** True when all nodes lie in one plane (z = 0), e.g. right after switching a 2D graph to 3D. */
  isFlat(): boolean {
    return this._graph.nodes.every((n) => !n.z);
  }

  /**
   * Runs a layout. `force` is animated and resolves when the simulation has settled; the other layouts
   * apply immediately. Pinned nodes stay in place.
   */
  runLayout(name: LayoutName = this.config.layout.name, options: Partial<LayoutOptions> = {}): Promise<void> {
    this.stopLayout();
    const g = this._graph;
    if (g.nodes.length === 0) return Promise.resolve();
    const cfg = this.config;
    placeNewNodes(g, cfg.dimension, cfg.layout.idealLength, cfg.layout.seed);
    const lo: LayoutOptions = {
      ...DEFAULT_LAYOUT_OPTIONS,
      dimension: cfg.dimension,
      spacing: cfg.layout.spacing,
      idealLength: cfg.layout.idealLength,
      gravity: cfg.layout.gravity,
      weightMode: cfg.layout.weightMode,
      direction: cfg.layout.direction,
      seed: cfg.layout.seed,
      gap: cfg.layout.gap,
      boxes: nodeBoxes(g, cfg, cfg.dimension === '3d'),
      ...options,
    };
    this.events.emit('layoutstart', { name });
    if (name === 'force') {
      this.sim = new ForceSimulation(g, lo);
      this.simName = name;
      this.requestRender();
      return new Promise<void>((resolve) => {
        this.simResolve = resolve;
      });
    }
    const pos = computeLayout(g, name, lo);
    g.setPositions([...pos].filter(([id]) => !g.getNode(id)?.pinned));
    if (cfg.camera.autoFit) this.pendingFit = true;
    this.events.emit('layoutend', { name, completed: true });
    this.requestRender();
    return Promise.resolve();
  }

  private simName: LayoutName = 'force';

  stopLayout(completed = false): void {
    if (!this.sim) return;
    this.sim = null;
    const resolve = this.simResolve;
    this.simResolve = null;
    if (completed && this.config.camera.autoFit) this.pendingFit = true;
    this.events.emit('layoutend', { name: this.simName, completed });
    resolve?.();
    this.requestRender();
  }

  get isLayoutRunning(): boolean {
    return this.sim !== null;
  }

  /** Frames the whole graph, or only the given nodes. */
  fit(ids?: string[]): void {
    const infos = ids ? ids.map((id) => this.nodeInfo.get(id)).filter((i): i is NodeInfo => !!i) : [...this.nodeInfo.values()];
    const subset = !!ids;
    const cam = this.camera;
    const dim3 = this.config.dimension === '3d';
    if (infos.length === 0) {
      this.controls.target.set(0, 0, 0);
      if (!dim3) {
        this.ortho.zoom = 1;
        this.ortho.position.set(0, 0, 1000);
      } else this.persp.position.set(0, 0, 300);
      this.ortho.updateProjectionMatrix();
      this.controls.update();
      this.requestRender();
      return;
    }
    let minX = Infinity, minY = Infinity, minZ = Infinity, maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    for (const i of infos) {
      const [x, y, z] = i.body.pos;
      minX = Math.min(minX, x - i.body.hw);
      maxX = Math.max(maxX, x + i.body.hw);
      minY = Math.min(minY, y - i.body.hh);
      maxY = Math.max(maxY, y + i.body.hh);
      minZ = Math.min(minZ, z);
      maxZ = Math.max(maxZ, z);
    }
    const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
    const pad = this.config.camera.fitPadding;
    const minSpan = subset ? 90 : 10; // a single match should not zoom in absurdly far
    const bw = Math.max(maxX - minX, minSpan), bh = Math.max(maxY - minY, minSpan), bd = maxZ - minZ;
    if (!dim3) {
      const aspect = this.width / this.height;
      const zoom = Math.min((ORTHO_HEIGHT * aspect) / bw, ORTHO_HEIGHT / bh) / pad;
      this.ortho.zoom = Math.min(this.config.camera.zoomMax, Math.max(this.config.camera.zoomMin, zoom));
      this.ortho.position.set(cx, cy, 1000);
      this.controls.target.set(cx, cy, 0);
      this.ortho.updateProjectionMatrix();
    } else {
      const radius = Math.max(0.5 * Math.hypot(bw, bh, bd), minSpan / 2);
      const vHalf = THREE.MathUtils.degToRad(this.persp.fov) / 2;
      const hHalf = Math.atan(Math.tan(vHalf) * (this.width / this.height));
      const dist = (radius / Math.sin(Math.min(vHalf, hHalf))) * pad * 0.8;
      const dir = this.tmpV.copy(cam.position).sub(this.controls.target);
      if (dir.lengthSq() < 1e-9) dir.set(0, 0, 1);
      dir.normalize();
      this.controls.target.set(cx, cy, cz);
      cam.position.set(cx, cy, cz).addScaledVector(dir, dist);
    }
    this.controls.update();
    this.requestRender();
  }

  zoomBy(factor: number): void {
    if (this.config.dimension === '2d') {
      const c = this.config.camera;
      this.ortho.zoom = Math.min(c.zoomMax, Math.max(c.zoomMin, this.ortho.zoom * factor));
      this.ortho.updateProjectionMatrix();
    } else {
      const off = this.tmpV.copy(this.persp.position).sub(this.controls.target).multiplyScalar(1 / factor);
      this.persp.position.copy(this.controls.target).add(off);
    }
    this.controls.update();
    this.requestRender();
  }

  setTool(tool: Tool): void {
    this.tool = tool;
    this.canvas.style.cursor = tool === 'connect' ? 'crosshair' : '';
    this.syncGizmo();
  }

  getTool(): Tool {
    return this.tool;
  }

  getSelection(): Selection {
    return { nodes: [...this.selNodes], edges: [...this.selEdges] };
  }

  setSelection(sel: Partial<Selection>): void {
    this.selNodes = new Set((sel.nodes ?? []).filter((id) => this._graph.hasNode(id)));
    this.selEdges = new Set((sel.edges ?? []).filter((id) => !!this._graph.getEdge(id)));
    this.dirtyNodes = this.dirtyEdges = true;
    this.events.emit('selection', this.getSelection());
    this.requestRender();
  }

  selectAll(): void {
    this.setSelection({ nodes: this._graph.nodes.map((n) => n.id) });
  }

  clearSelection(): void {
    if (this.selNodes.size || this.selEdges.size) this.setSelection({});
  }

  getNodeStyle(id: string): NodeStyle | undefined {
    return this.nodeInfo.get(id)?.style;
  }

  getEdgeStyle(id: string): EdgeStyle | undefined {
    return this.edgeInfo.get(id)?.style;
  }

  /** True while the view is shown full screen (native Fullscreen API or the CSS fallback). */
  get isFullscreen(): boolean {
    return document.fullscreenElement === this.container || this.container.classList.contains('gs-pseudo-fullscreen');
  }

  /**
   * Switches the whole view (container) in or out of full screen. Uses the Fullscreen API and falls back to a
   * fixed, viewport-filling container where it is unavailable (e.g. iPhone Safari). Must be called from a user gesture.
   * Esc leaves full screen in both variants.
   */
  async toggleFullscreen(force?: boolean): Promise<void> {
    const want = force ?? !this.isFullscreen;
    if (want === this.isFullscreen) return;
    const c = this.container;
    if (want) {
      if (typeof c.requestFullscreen === 'function') {
        try {
          await c.requestFullscreen();
          return; // the fullscreenchange event finishes the job
        } catch {
          /* denied: use the fallback below */
        }
      }
      c.classList.add('gs-pseudo-fullscreen');
    } else if (document.fullscreenElement === c) {
      await document.exitFullscreen();
      return;
    } else c.classList.remove('gs-pseudo-fullscreen');
    this.onFullscreenChange();
  }

  /** Icon button like in video players: four corners pointing out (enter) or in (exit). */
  private updateFullscreenButton(): void {
    const b = this.fsButton;
    if (!b) return;
    const fs = this.isFullscreen;
    const path = fs ? 'M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5' : 'M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5';
    b.innerHTML = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`;
    const label = fs ? 'Exit full screen' : 'Full screen';
    b.title = label;
    b.setAttribute('aria-label', label);
  }

  private onFullscreenChange = (): void => {
    if (this.disposed) return;
    const fs = this.isFullscreen;
    this.updateFullscreenButton();
    this.resize();
    this.events.emit('fullscreenchange', { fullscreen: fs });
  };

  /** Opens the url of a node or edge according to `links` (self / blank / panel / event). */
  openLink(kind: 'node' | 'edge', id: string): boolean {
    const item = kind === 'node' ? this._graph.getNode(id) : this._graph.getEdge(id);
    const resolved = resolveUrl(item?.url, this.config.links);
    if (!item || !item.url || !resolved) return false;
    const payload = { url: item.url, resolved, kind, id, handled: false };
    this.events.emit('link', payload);
    if (payload.handled || this.config.links.target === 'event') return true;
    switch (this.config.links.target) {
      case 'blank': window.open(resolved, '_blank', 'noopener'); break;
      case 'panel': this.openPanel(resolved, (item as { label?: string }).label ?? id); break;
      default: window.location.assign(resolved);
    }
    return true;
  }

  closePanel(): void {
    this.panelEl?.remove();
    this.panelEl = null;
  }

  /** PNG (or other) data URL of the current view including the background. */
  exportImage(type = 'image/png', quality?: number): string {
    this.frame();
    const out = document.createElement('canvas');
    out.width = this.canvas.width;
    out.height = this.canvas.height;
    const ctx = out.getContext('2d')!;
    const bg = this.config.background;
    if (!bg.transparent) {
      if (bg.gradientTo) {
        const g = ctx.createLinearGradient(0, 0, 0, out.height);
        g.addColorStop(0, bg.color);
        g.addColorStop(1, bg.gradientTo);
        ctx.fillStyle = g;
      } else ctx.fillStyle = bg.color;
      ctx.fillRect(0, 0, out.width, out.height);
    }
    ctx.drawImage(this.canvas, 0, 0);
    return out.toDataURL(type, quality);
  }

  resize(): void {
    const w = Math.max(1, this.container.clientWidth);
    const h = Math.max(1, this.container.clientHeight);
    this.width = w;
    this.height = h;
    this.renderer.setPixelRatio(this.config.render.pixelRatio ?? Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.setSize(w, h);
    const aspect = w / h;
    this.persp.aspect = aspect;
    this.persp.updateProjectionMatrix();
    this.ortho.left = (-ORTHO_HEIGHT * aspect) / 2;
    this.ortho.right = (ORTHO_HEIGHT * aspect) / 2;
    this.ortho.top = ORTHO_HEIGHT / 2;
    this.ortho.bottom = -ORTHO_HEIGHT / 2;
    this.ortho.updateProjectionMatrix();
    for (const b of this.buckets) (b.mesh.material as LineMaterial).resolution.set(w, h);
    if (this.controls && !this.orbit) (this.controls as unknown as TrackballControls).handleResize();
    this.dirtyLabels = true;
    this.requestRender();
  }

  destroy(): void {
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    cancelAnimationFrame(this.hoverRaf);
    this.ro?.disconnect();
    this.unsubGraph();
    this.stopLayout();
    this.root.removeEventListener('pointerdown', this.onPointerDown, true);
    window.removeEventListener('keydown', this.onKeyDown);
    window.removeEventListener('keyup', this.onKeyUp);
    window.removeEventListener('blur', this.onBlur);
    document.removeEventListener('fullscreenchange', this.onFullscreenChange);
    this.container.classList.remove('gs-pseudo-fullscreen');
    this.setAxisGuide(null);
    window.clearInterval(this.statsTimer);
    this.disposeGizmo();
    this.disposeControls();
    this.clearScene();
    for (const g of this.geoms.values()) g.dispose();
    this.tex.clear();
    this.renderer.dispose();
    this.root.remove();
    this.container.classList.remove('gs-container');
    this.events.clear();
  }

  // ------------------------------------------------------------------ setup helpers

  private subscribe(): void {
    this.unsubGraph = this._graph.events.on('change', this.onGraphChange);
  }

  private onGraphChange = (e: { kind: ChangeKind }): void => {
    if (e.kind === 'position') this.dirtyPositions = true;
    else {
      if (this.sim) this.stopLayout();
      this.searchIndex = null;
      this.dirtyStructure = true;
    }
    this.requestRender();
  };

  private afterLoad(): void {
    const missing = this._graph.nodes.some((n) => n.x === undefined || n.y === undefined);
    this.pendingFit = this.config.camera.autoFit;
    this.pendingLayout = missing && this.config.layout.autoRun;
    this.dirtyStructure = true;
    this.requestRender();
  }

  /** @param preserve keep the current camera pose (used when only the control scheme changes) */
  private setupCamera(preserve = false): void {
    const dim3 = this.config.dimension === '3d';
    const free = dim3 && this.config.camera.rotation === 'free';
    const target = this.controls ? this.controls.target.clone() : null;
    this.disposeControls();
    this.camera = dim3 ? this.persp : this.ortho;
    if (!preserve) {
      if (!dim3) {
        this.ortho.position.set(0, 0, 1000);
        this.ortho.zoom = 1;
      } else this.persp.position.set(0, 0, 300);
    }
    if (dim3) this.persp.up.set(0, 1, 0);
    if (free) {
      // Trackball: unlimited rotation around every axis, the horizon is not kept level.
      const t = new TrackballControls(this.camera, this.canvas);
      t.rotateSpeed = 2.5;
      t.zoomSpeed = 1.2;
      t.panSpeed = 0.8;
      t.staticMoving = false;
      t.dynamicDampingFactor = 0.12;
      t.keys = ['', '', '']; // no A/S/D key modes, they would collide with editor shortcuts
      t.addEventListener('change', this.onCameraChange);
      this.disposeControls = () => {
        t.removeEventListener('change', this.onCameraChange);
        t.dispose();
      };
      this.orbit = null;
      this.controls = t;
    } else {
      const c = new OrbitControls(this.camera, this.canvas);
      c.enableDamping = this.config.camera.damping;
      c.zoomToCursor = true;
      c.addEventListener('change', this.onCameraChange);
      if (!dim3) {
        c.enableRotate = false;
        c.screenSpacePanning = true;
        c.mouseButtons = { LEFT: THREE.MOUSE.PAN, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
        c.touches = { ONE: THREE.TOUCH.PAN, TWO: THREE.TOUCH.DOLLY_PAN };
      } else {
        c.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
        c.touches = { ONE: THREE.TOUCH.ROTATE, TWO: THREE.TOUCH.DOLLY_PAN };
      }
      this.disposeControls = () => {
        c.removeEventListener('change', this.onCameraChange);
        c.dispose();
      };
      this.orbit = c;
      this.controls = c;
    }
    if (preserve && target) this.controls.target.copy(target);
    this.applyControlLimits();
    this.controls.update();
    this.setupGizmo();
  }

  private applyControlLimits(): void {
    const cam = this.config.camera;
    if (this.orbit) {
      this.orbit.minZoom = cam.zoomMin;
      this.orbit.maxZoom = cam.zoomMax;
    }
    this.controls.minDistance = 5;
    this.controls.maxDistance = 50000;
  }

  /** Trackball controls only move the camera when `update()` runs, so keep frames coming while the user interacts. */
  private get needsContinuousFrames(): boolean {
    return !this.orbit && this.config.dimension === '3d' && (this.pointerIsDown || performance.now() < this.activeUntil);
  }

  private onCameraChange = (): void => {
    if (this.config.label.mode === 'screen' || this.config.dimension === '3d') this.dirtyLabels = true;
    this.requestRender();
  };

  private applyAppearance(): void {
    const c = this.config;
    const bg = c.background;
    this.root.style.background = bg.transparent ? 'transparent' : bg.gradientTo ? `linear-gradient(${bg.color}, ${bg.gradientTo})` : bg.color;
    for (const k of this.appliedVars) this.root.style.removeProperty(`--gs-${k}`);
    this.appliedVars = Object.keys(c.ui.cssVars);
    for (const [k, v] of Object.entries(c.ui.cssVars)) this.root.style.setProperty(`--gs-${k}`, v);
    this.tooltipEl.hidden = true;
  }

  private buildControls(): void {
    this.controlsEl?.remove();
    this.controlsEl = null;
    if (!this.config.ui.controls) return;
    const el = document.createElement('div');
    el.className = 'gs-controls gs-ui';
    const mk = (text: string, title: string, fn: () => void): HTMLButtonElement => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'gs-btn';
      b.textContent = text;
      b.title = title;
      b.setAttribute('aria-label', title);
      b.addEventListener('click', fn);
      el.appendChild(b);
      return b;
    };
    mk('+', 'Zoom in', () => this.zoomBy(1.4));
    mk('\u2212', 'Zoom out', () => this.zoomBy(1 / 1.4));
    mk('Fit', 'Fit graph to view', () => this.fit());
    this.dimButton = mk(this.config.dimension === '2d' ? '3D' : '2D', 'Switch between 2D and 3D', () => {
      this.setDimension(this.config.dimension === '2d' ? '3d' : '2d');
    });
    this.fsButton = null;
    if (this.config.ui.fullscreen) {
      this.fsButton = mk('', 'Full screen', () => {
        void this.toggleFullscreen();
      });
      this.updateFullscreenButton();
    }
    this.helpButton = null;
    if (this.config.ui.help) {
      this.helpButton = mk('?', 'Help: the controls of this view', () => this.toggleHelp());
      this.helpButton.classList.add('gs-help-btn');
    }
    this.root.appendChild(el);
    this.controlsEl = el;
  }

  // ------------------------------------------------------------------ render loop

  private requestRender(): void {
    if (this.raf || this.disposed) return;
    this.raf = requestAnimationFrame(this.tick);
  }

  private tick = (): void => {
    this.raf = 0;
    if (this.disposed) return;
    this.frame();
    if (this.sim || this.needsContinuousFrames) this.requestRender();
  };

  private frame(): void {
    const t0 = performance.now();
    if (this.sim) this.stepSimulation();
    if (this.dirtyStructure) {
      const r0 = performance.now();
      this.rebuildStructure();
      this.perf.rebuildMs = performance.now() - r0;
    }
    if (this.pendingFit) {
      this.pendingFit = false;
      this.fit();
    }
    if (this.pendingLayout) {
      this.pendingLayout = false;
      void this.runLayout();
    }
    if (this.dirtyPositions) {
      const p0 = performance.now();
      this.updatePositions();
      this.perf.positionsMs = performance.now() - p0;
    }
    if (this.dirtyNodes) {
      this.dirtyNodes = false;
      this.updateNodeInstances();
    }
    if (this.dirtyEdges) {
      this.dirtyEdges = false;
      this.writeEdges();
    }
    if (this.dirtyLabels) {
      this.dirtyLabels = false;
      this.updateLabels();
    }
    this.controls.update();
    this.updateChip();
    if (this.config.dimension === '3d') {
      this.headlight.position.copy(this.persp.position);
      this.headlight.target.position.copy(this.controls.target);
      this.headlight.target.updateMatrixWorld();
    }
    const t1 = performance.now();
    this.renderer.render(this.scene, this.camera);
    this.recordFrame(t0, t1, performance.now());
  }

  private recordFrame(t0: number, t1: number, t2: number): void {
    const p = this.perf;
    const i = p.n % 120;
    p.update[i] = t1 - t0;
    p.render[i] = t2 - t1;
    p.n++;
    p.stamps.push(t2);
    while (p.stamps.length && t2 - p.stamps[0] > 1000) p.stamps.shift();
  }

  private stepSimulation(): void {
    const sim = this.sim;
    if (!sim) return;
    const n = this._graph.nodes.length;
    const steps = n <= 1500 ? 3 : n <= 5000 ? 2 : 1;
    for (const id of this.dragIds) {
      const nd = this._graph.getNode(id);
      if (nd) sim.pin(id, [nd.x ?? 0, nd.y ?? 0, nd.z ?? 0]);
    }
    const s0 = performance.now();
    for (let i = 0; i < steps; i++) sim.step();
    sim.commit(this._graph);
    this.perf.stepMs = performance.now() - s0;
    if (sim.alpha < 0.02) this.stopLayout(true);
  }

  // ------------------------------------------------------------------ scene construction

  private color(c: string): THREE.Color {
    let col = this.colors.get(c);
    if (!col) {
      col = new THREE.Color(c);
      this.colors.set(c, col);
    }
    return col;
  }

  private geometryFor(key: string): THREE.BufferGeometry {
    let g = this.geoms.get(key);
    if (g) return g;
    switch (key) {
      case 'circle3d': g = new THREE.SphereGeometry(0.5, 24, 16); break;
      case 'square3d':
      case 'rectangle3d': g = new THREE.BoxGeometry(1, 1, 1); break;
      case 'diamond3d': g = new THREE.OctahedronGeometry(0.62); break;
      case 'hexagon3d': g = new THREE.CylinderGeometry(0.5, 0.5, 1, 6); g.rotateX(Math.PI / 2); g.rotateZ(Math.PI / 2); break;
      case 'triangle3d': g = new THREE.CylinderGeometry(0.5, 0.5, 1, 3); g.rotateX(-Math.PI / 2); break;
      case 'square':
      case 'rectangle': g = new THREE.PlaneGeometry(1, 1); break;
      case 'diamond': g = new THREE.CircleGeometry(0.5, 4); break;
      case 'hexagon': g = new THREE.CircleGeometry(0.5, 6); break;
      case 'triangle': g = new THREE.CircleGeometry(0.5, 3); g.rotateZ(Math.PI / 2); break;
      case 'arrow': g = new THREE.ConeGeometry(0.5, 1, 14); g.rotateZ(-Math.PI / 2); g.translate(-0.5, 0, 0); break;
      default: g = new THREE.CircleGeometry(0.5, 40);
    }
    this.geoms.set(key, g);
    return g;
  }

  /** Material flags that differ between 2D (ordered by renderOrder) and 3D (depth buffer). */
  private applyMode(m: THREE.Material, opacity: number): void {
    const dim3 = this.config.dimension === '3d';
    m.transparent = dim3 ? opacity < 1 : true;
    m.opacity = opacity;
    m.depthTest = dim3;
    m.depthWrite = dim3;
  }

  private clearScene(): void {
    for (const l of this.layers.values()) {
      this.scene.remove(l.body, l.outline);
      (l.body.material as THREE.Material).dispose();
      (l.outline.material as THREE.Material).dispose();
      l.body.dispose();
      l.outline.dispose();
    }
    this.layers.clear();
    for (const b of this.buckets) {
      this.scene.remove(b.mesh);
      b.mesh.geometry.dispose();
      (b.mesh.material as THREE.Material).dispose();
    }
    this.buckets = [];
    if (this.arrowMesh) {
      this.scene.remove(this.arrowMesh);
      (this.arrowMesh.material as THREE.Material).dispose();
      this.arrowMesh.dispose();
      this.arrowMesh = null;
    }
    for (const i of this.nodeInfo.values()) {
      if (i.sprite) this.dropSprite(i.sprite);
      if (i.badge) this.dropSprite(i.badge);
    }
    for (const i of this.edgeInfo.values()) {
      if (i.sprite) this.dropSprite(i.sprite);
      if (i.badge) this.dropSprite(i.badge);
    }
    this.nodeInfo.clear();
    this.edgeInfo.clear();
  }

  private dropSprite(s: THREE.Sprite): void {
    this.scene.remove(s);
    s.material.dispose();
  }

  private makeSprite(img: TextImage, order: number): THREE.Sprite {
    const dim3 = this.config.dimension === '3d';
    const mat = new THREE.SpriteMaterial({ map: img.texture, transparent: true, depthTest: dim3, depthWrite: false });
    const s = new THREE.Sprite(mat);
    s.renderOrder = order;
    s.frustumCulled = false;
    this.scene.add(s);
    return s;
  }

  private rebuildStructure(): void {
    this.dirtyStructure = false;
    this.clearScene();
    const cfg = this.config;
    const g = this._graph;
    const dim3 = cfg.dimension === '3d';
    placeNewNodes(g, cfg.dimension, cfg.layout.idealLength, cfg.layout.seed);
    for (const id of [...this.selNodes]) if (!g.hasNode(id)) this.selNodes.delete(id);
    for (const id of [...this.selEdges]) if (!g.getEdge(id)) this.selEdges.delete(id);
    if (this.hoverNode && !g.hasNode(this.hoverNode)) this.hoverNode = null;
    if (this.hoverEdge && !g.getEdge(this.hoverEdge)) this.hoverEdge = null;

    // nodes
    const groups = buildGroupIndex(g);
    const byLayer = new Map<string, NodeInfo[]>();
    for (const n of g.nodes) {
      if (this.hiddenGroups.has(n.group ?? NO_GROUP)) continue;
      const style = resolveNodeStyle(n, cfg, groups);
      const ext = geometry.nodeExtents(style.shape, style.size, cfg.node.aspect, dim3);
      const info: NodeInfo = {
        node: n,
        style,
        body: { pos: [0, 0, 0], hw: ext.hw, hh: ext.hh, ellipse: geometry.isEllipseShape(style.shape) },
        layerKey: null,
        layer: null,
        slot: -1,
      };
      if (style.shape === 'card') {
        info.card = this.tex.card(n, style, cfg);
        info.body.hw = info.card.w / 2;
        info.body.hh = info.card.h / 2;
        info.body.ellipse = false;
        if (dim3) info.body.hw = info.body.hh = Math.max(info.body.hw, info.body.hh);
        info.sprite = this.makeSprite(info.card, 4);
      } else {
        info.layerKey = dim3 ? `${style.shape}3d` : style.shape;
        const list = byLayer.get(info.layerKey) ?? [];
        list.push(info);
        byLayer.set(info.layerKey, list);
      }
      this.nodeInfo.set(n.id, info);
    }
    for (const [key, list] of byLayer) {
      const geo = this.geometryFor(key);
      const bodyMat = dim3 ? new THREE.MeshLambertMaterial() : new THREE.MeshBasicMaterial();
      this.applyMode(bodyMat, cfg.node.opacity);
      const outMat = new THREE.MeshBasicMaterial({ side: dim3 ? THREE.BackSide : THREE.FrontSide });
      this.applyMode(outMat, cfg.node.opacity);
      const body = new THREE.InstancedMesh(geo, bodyMat, list.length);
      const outline = new THREE.InstancedMesh(geo, outMat, list.length);
      for (const m of [body, outline]) {
        m.frustumCulled = false;
        m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      }
      outline.renderOrder = 3;
      body.renderOrder = 4;
      const layer: Layer = { key, body, outline };
      list.forEach((info, i) => {
        info.layer = layer;
        info.slot = i;
        body.setColorAt(i, this.color(info.style.color));
        outline.setColorAt(i, this.color(info.style.borderColor));
      });
      this.layers.set(key, layer);
      this.scene.add(outline, body);
    }
    if (cfg.label.show && g.nodes.length <= cfg.label.maxCount) {
      for (const info of this.nodeInfo.values()) {
        if (info.card) continue;
        const sub = info.node.sublabel ? { text: info.node.sublabel, size: cfg.label.subSize, color: cfg.label.subColor } : undefined;
        const img = this.tex.text(info.node.label ?? info.node.id, { ...cfg.label, color: info.style.labelColor }, sub);
        info.sprite = this.makeSprite(img, 5);
      }
    }

    // edges
    let min = Infinity;
    let max = -Infinity;
    for (const e of g.edges) {
      const w = g.weightOf(e);
      min = Math.min(min, w);
      max = Math.max(max, w);
    }
    const groupsByPair = new Map<string, EdgeInfo[]>();
    const bucketMap = new Map<string, Bucket>();
    let arrows = 0;
    for (const e of g.edges) {
      if (!this.nodeInfo.has(e.source) || !this.nodeInfo.has(e.target)) continue; // an end is hidden
      const weight = g.weightOf(e);
      const style = resolveEdgeStyle(e, weight, cfg, { min, max });
      const self = e.source === e.target;
      const info: EdgeInfo = {
        edge: e, style, weight, directed: g.isDirected(e), index: 0, count: 1, flip: !self && e.source > e.target, self,
        path: [], arrowSlot: -1, bucketKey: `${style.width}|${style.dashed ? 1 : 0}`,
      };
      const pair = self ? `s\u0000${e.source}` : e.source < e.target ? `${e.source}\u0000${e.target}` : `${e.target}\u0000${e.source}`;
      const list = groupsByPair.get(pair) ?? [];
      list.push(info);
      groupsByPair.set(pair, list);
      this.edgeInfo.set(e.id, info);
      if (info.directed && cfg.edge.arrows) info.arrowSlot = arrows++;
      let bucket = bucketMap.get(info.bucketKey);
      if (!bucket) {
        const mat = new LineMaterial({
          color: 0xffffff, linewidth: style.width, vertexColors: true, dashed: style.dashed, dashSize: cfg.edge.dashSize, gapSize: cfg.edge.gapSize,
        });
        mat.resolution.set(this.width, this.height);
        this.applyMode(mat, cfg.edge.opacity);
        const mesh = new LineSegments2(new LineSegmentsGeometry(), mat);
        mesh.frustumCulled = false;
        mesh.renderOrder = 1;
        mesh.visible = false;
        this.scene.add(mesh);
        bucket = { key: info.bucketKey, mesh, edges: [], dashed: style.dashed };
        bucketMap.set(info.bucketKey, bucket);
      }
      bucket.edges.push(info);
    }
    for (const list of groupsByPair.values()) list.forEach((info, i) => { info.index = i; info.count = list.length; });
    this.buckets = [...bucketMap.values()];
    if (arrows > 0) {
      const mat = new THREE.MeshBasicMaterial();
      this.applyMode(mat, cfg.edge.opacity);
      const mesh = new THREE.InstancedMesh(this.geometryFor('arrow'), mat, arrows);
      mesh.frustumCulled = false;
      mesh.renderOrder = 2;
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      for (let i = 0; i < arrows; i++) mesh.setColorAt(i, this.color('#ffffff'));
      this.arrowMesh = mesh;
      this.scene.add(mesh);
    }
    if (g.edges.length <= cfg.weight.maxCount) {
      for (const info of this.edgeInfo.values()) {
        const text = this.edgeText(info);
        if (!text) continue;
        info.img = this.tex.text(text, { ...cfg.weight, maxChars: cfg.label.maxChars });
        info.sprite = this.makeSprite(info.img, 5);
      }
    }

    if (cfg.links.badge && cfg.interaction.openLinks !== 'never') {
      const img = this.tex.badge(cfg.links.badgeColor);
      for (const info of this.nodeInfo.values()) if (resolveUrl(info.node.url, cfg.links)) info.badge = this.makeSprite(img, 6);
      for (const info of this.edgeInfo.values()) if (resolveUrl(info.edge.url, cfg.links)) info.badge = this.makeSprite(img, 6);
    }

    for (const id of [...this.selNodes]) if (!this.nodeInfo.has(id)) this.selNodes.delete(id);
    for (const id of [...this.selEdges]) if (!this.edgeInfo.has(id)) this.selEdges.delete(id);
    this.dirtyPositions = false;
    this.dirtyNodes = this.dirtyEdges = false;
    this.updatePositions();
    this.updateLegend();
  }

  private edgeText(info: EdgeInfo): string {
    const cfg = this.config.weight;
    const showW = cfg.show === 'always' || (cfg.show === 'auto' && info.weight !== 1);
    const w = showW ? String(Number(info.weight.toFixed(cfg.decimals))) : '';
    const l = info.edge.label ?? '';
    return l && w ? `${l} (${w})` : l || w;
  }

  // ------------------------------------------------------------------ per-frame updates

  private updatePositions(): void {
    this.dirtyPositions = false;
    const dim3 = this.config.dimension === '3d';
    for (const info of this.nodeInfo.values()) {
      const n = info.node;
      info.body.pos[0] = n.x ?? 0;
      info.body.pos[1] = n.y ?? 0;
      info.body.pos[2] = dim3 ? n.z ?? 0 : 0;
    }
    this.updateNodeInstances();
    this.computePaths();
    this.writeEdges();
    this.updateLabels();
  }

  private updateNodeInstances(): void {
    const cfg = this.config;
    const dim3 = cfg.dimension === '3d';
    const m = this.tmpM;
    for (const [id, info] of this.nodeInfo) {
      const layer = info.layer;
      if (!layer) continue;
      const sel = this.selNodes.has(id);
      const hov = id === this.hoverNode;
      const bw = sel ? cfg.selection.width : hov ? cfg.selection.width * 0.8 : info.style.borderWidth;
      const sx = info.body.hw * 2;
      const sy = info.body.hh * 2;
      const [x, y, z] = info.body.pos;
      m.compose(this.tmpV.set(x, y, z), IDENTITY_Q, this.tmpS.set(sx, sy, dim3 ? sy : 1));
      layer.body.setMatrixAt(info.slot, m);
      m.compose(this.tmpV.set(x, y, z), IDENTITY_Q, this.tmpS.set(sx + 2 * bw, sy + 2 * bw, dim3 ? sy + 2 * bw : 1));
      layer.outline.setMatrixAt(info.slot, m);
      layer.outline.setColorAt(info.slot, this.color(sel ? cfg.selection.color : hov ? cfg.selection.hoverColor : info.style.borderColor));
    }
    for (const l of this.layers.values()) {
      l.body.instanceMatrix.needsUpdate = true;
      l.outline.instanceMatrix.needsUpdate = true;
      if (l.outline.instanceColor) l.outline.instanceColor.needsUpdate = true;
    }
    this.syncGizmo();
  }

  private computePaths(): void {
    const cfg = this.config;
    const opts: geometry.PathOptions = { spacing: cfg.edge.curveSpacing, segments: 16, dim3: cfg.dimension === '3d', loopScale: cfg.edge.loopSize };
    for (const info of this.edgeInfo.values()) {
      const a = this.nodeInfo.get(info.edge.source)?.body;
      const b = this.nodeInfo.get(info.edge.target)?.body;
      if (!a || !b) {
        info.path = [];
        continue;
      }
      let path = geometry.edgePath(a, b, info.index, info.count, info.flip, info.self, opts);
      info.tip = undefined;
      if (info.arrowSlot >= 0 && path.length >= 2) {
        info.tip = geometry.tipOf(path);
        path = geometry.shortenEnd(path, cfg.edge.arrowSize * 0.9);
      }
      info.path = path;
    }
  }

  private edgeColor(info: EdgeInfo): THREE.Color {
    const sel = this.config.selection;
    if (this.selEdges.has(info.edge.id)) return this.color(sel.color);
    if (info.edge.id === this.hoverEdge) return this.color(sel.hoverColor);
    return this.color(info.style.color);
  }

  /** Writes line and arrow buffers from the cached paths. */
  private writeEdges(): void {
    for (const b of this.buckets) {
      let segs = 0;
      for (const e of b.edges) segs += Math.max(0, e.path.length - 1);
      const pos = new Float32Array(segs * 6);
      const col = new Float32Array(segs * 6);
      let o = 0;
      for (const e of b.edges) {
        const c = this.edgeColor(e);
        for (let i = 1; i < e.path.length; i++) {
          const p = e.path[i - 1];
          const q = e.path[i];
          pos[o] = p[0]; pos[o + 1] = p[1]; pos[o + 2] = p[2];
          pos[o + 3] = q[0]; pos[o + 4] = q[1]; pos[o + 5] = q[2];
          col[o] = col[o + 3] = c.r;
          col[o + 1] = col[o + 4] = c.g;
          col[o + 2] = col[o + 5] = c.b;
          o += 6;
        }
      }
      const geo = new LineSegmentsGeometry();
      if (segs > 0) {
        geo.setPositions(pos);
        geo.setColors(col);
      }
      b.mesh.geometry.dispose();
      b.mesh.geometry = geo;
      b.mesh.visible = segs > 0;
      if (segs > 0 && b.dashed) b.mesh.computeLineDistances();
    }
    if (this.arrowMesh) {
      const len = this.config.edge.arrowSize;
      for (const info of this.edgeInfo.values()) {
        if (info.arrowSlot < 0) continue;
        if (!info.tip) {
          this.arrowMesh.setMatrixAt(info.arrowSlot, this.tmpM.makeScale(0, 0, 0));
          continue;
        }
        const d = info.tip.dir;
        this.tmpQ.setFromUnitVectors(X_AXIS, this.tmpV2.set(d[0], d[1], d[2]));
        this.tmpM.compose(this.tmpV.set(info.tip.tip[0], info.tip.tip[1], info.tip.tip[2]), this.tmpQ, this.tmpS.set(len, len * 0.8, len * 0.8));
        this.arrowMesh.setMatrixAt(info.arrowSlot, this.tmpM);
        this.arrowMesh.setColorAt(info.arrowSlot, this.edgeColor(info));
      }
      this.arrowMesh.instanceMatrix.needsUpdate = true;
      if (this.arrowMesh.instanceColor) this.arrowMesh.instanceColor.needsUpdate = true;
    }
  }

  private updateLabels(): void {
    const cfg = this.config;
    const screen = cfg.label.mode === 'screen';
    const dim3 = cfg.dimension === '3d';
    for (const info of this.nodeInfo.values()) {
      const s = info.sprite;
      if (!s) continue;
      const [x, y, z] = info.body.pos;
      if (info.card) {
        s.position.set(x, y, z);
        s.scale.set(info.card.w, info.card.h, 1);
        continue;
      }
      const img = (s.material.map as THREE.CanvasTexture).image as HTMLCanvasElement;
      const res = this.tex.resolution;
      const u = screen ? 1 / this.pxPerUnitAt(x, y, z) : 1;
      const w = (img.width / res) * u;
      const h = (img.height / res) * u;
      s.scale.set(w, h, 1);
      s.position.set(x, y - info.body.hh - cfg.label.gap * u - h / 2, z);
      if (dim3) this.towardCamera(s.position, info.body.hw + 1);
    }
    for (const info of this.edgeInfo.values()) {
      const s = info.sprite;
      if (!s || !info.img || info.path.length < 2) {
        if (s) s.visible = false;
        continue;
      }
      const p = geometry.pointAtFraction(info.path, 0.5);
      const u = screen ? 1 / this.pxPerUnitAt(p[0], p[1], p[2]) : 1;
      s.visible = true;
      s.scale.set(info.img.w * u, info.img.h * u, 1);
      s.position.set(p[0], p[1], p[2]);
      if (dim3) this.towardCamera(s.position, 1.5);
    }
    this.updateBadges();
  }

  /** Link badges: top right of a node, beside the middle of an edge. */
  private updateBadges(): void {
    const size = this.config.links.badgeSize;
    const dim3 = this.config.dimension === '3d';
    for (const info of this.nodeInfo.values()) {
      const b = info.badge;
      if (!b) continue;
      const [x, y, z] = info.body.pos;
      b.scale.set(size, size, 1);
      b.position.set(x + info.body.hw * 0.72, y + info.body.hh * 0.72, z);
      if (dim3) this.towardCamera(b.position, info.body.hw + 2);
    }
    for (const info of this.edgeInfo.values()) {
      const b = info.badge;
      if (!b) continue;
      if (info.path.length < 2) {
        b.visible = false;
        continue;
      }
      const p = geometry.pointAtFraction(info.path, 0.5);
      b.visible = true;
      b.scale.set(size, size, 1);
      b.position.set(p[0] + size * 0.9, p[1] + size * 0.9, p[2]);
      if (dim3) this.towardCamera(b.position, 2);
    }
  }

  /** The "Open page" chip next to a single selected node or edge that has a url. */
  private updateChip(): void {
    const el = this.chipEl;
    const cfg = this.config;
    const dragging = this.dragIds.length > 0 || this.gizmoDragging || (this.drag?.type === 'nodes' && this.drag.moved);
    let target: { kind: 'node' | 'edge'; id: string; at: Vec3; dx: number; dy: number } | null = null;
    if (cfg.links.chip && cfg.interaction.openLinks !== 'never' && !dragging) {
      if (this.selNodes.size === 1 && this.selEdges.size === 0) {
        const id = [...this.selNodes][0];
        const info = this.nodeInfo.get(id);
        if (info && resolveUrl(info.node.url, cfg.links)) {
          const ppu = this.pxPerUnitAt(info.body.pos[0], info.body.pos[1], info.body.pos[2]);
          target = { kind: 'node', id, at: info.body.pos, dx: info.body.hw * ppu + 8, dy: -info.body.hh * ppu - 4 };
        }
      } else if (this.selEdges.size === 1 && this.selNodes.size === 0) {
        const id = [...this.selEdges][0];
        const info = this.edgeInfo.get(id);
        if (info && info.path.length >= 2 && resolveUrl(info.edge.url, cfg.links)) target = { kind: 'edge', id, at: geometry.pointAtFraction(info.path, 0.5), dx: 12, dy: -12 };
      }
    }
    if (!target) {
      if (!el.hidden) el.hidden = true;
      this.chipTarget = null;
      return;
    }
    this.camera.updateMatrixWorld();
    const v = this.tmpV.set(target.at[0], target.at[1], target.at[2]).project(this.camera);
    if (v.z < -1 || v.z > 1) {
      el.hidden = true;
      this.chipTarget = null;
      return;
    }
    const label = `${cfg.links.chipLabel} \u2197`;
    if (el.textContent !== label) el.textContent = label;
    this.chipTarget = { kind: target.kind, id: target.id };
    el.hidden = false;
    const x = (v.x * 0.5 + 0.5) * this.width + target.dx;
    const y = (-v.y * 0.5 + 0.5) * this.height + target.dy;
    el.style.left = `${Math.max(4, Math.min(x, this.width - el.offsetWidth - 4))}px`;
    el.style.top = `${Math.max(4, Math.min(y, this.height - el.offsetHeight - 4))}px`;
  }

  /** "Ctrl+click to open the page", or "" when the item has no usable link. */
  private linkHint(url: string | undefined): string {
    const cfg = this.config;
    if (!cfg.links.hint || cfg.interaction.openLinks === 'never' || !resolveUrl(url, cfg.links)) return '';
    const mac = typeof navigator !== 'undefined' && /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent);
    const gesture = describeLinkGesture(cfg.interaction.openLinks, mac);
    return cfg.links.chip ? `${gesture} to open the page, or select it and use \u201c${cfg.links.chipLabel}\u201d` : `${gesture} to open the page`;
  }

  /** Moves a point toward the camera so a label always sits in front of the node it belongs to. */
  private towardCamera(pos: THREE.Vector3, distance: number): void {
    const d = this.tmpV2.copy(this.persp.position).sub(pos);
    if (d.lengthSq() < 1e-9) return;
    pos.addScaledVector(d.normalize(), distance);
  }

  /** CSS pixels per world unit at a world position. */
  private pxPerUnitAt(x: number, y: number, z: number): number {
    if (this.camera === this.ortho) return this.height / ((this.ortho.top - this.ortho.bottom) / this.ortho.zoom);
    const v = this.tmpV2.set(x, y, z).applyMatrix4(this.persp.matrixWorldInverse);
    const d = Math.max(0.001, -v.z);
    return this.height / (2 * Math.tan(THREE.MathUtils.degToRad(this.persp.fov) / 2) * d);
  }

  // ------------------------------------------------------------------ transform gizmo

  getGizmoMode(): GizmoMode {
    return this.gizmoMode;
  }

  /**
   * Move, rotate or scale. With one selected node only `translate` does something; rotating and scaling act on
   * the positions of two or more selected nodes around the center of the selection.
   */
  setGizmoMode(mode: GizmoMode): void {
    this.gizmoMode = mode;
    this.tc?.setMode(mode);
    this.applyGizmoAxes();
    this.syncGizmo();
    this.events.emit('gizmomode', { mode });
    this.requestRender();
  }

  private disposeGizmo(): void {
    if (!this.tc) return;
    this.tc.detach();
    if (this.tcHelper) this.scene.remove(this.tcHelper);
    this.tc.dispose();
    this.tc = null;
    this.tcHelper = null;
    this.gizmoDragging = false;
  }

  /** (Re)creates the gizmo for the current camera. Called whenever the camera or the configuration changes. */
  private setupGizmo(): void {
    this.disposeGizmo();
    if (!this.config.interaction.gizmo) return;
    const tc = new TransformControls(this.camera, this.canvas);
    tc.setMode(this.gizmoMode);
    tc.setSpace(this.config.gizmo.space);
    tc.setSize(this.config.gizmo.size);
    tc.addEventListener('dragging-changed', ((e: { value: boolean }) => {
      this.controls.enabled = !e.value;
      if (e.value) this.beginGizmoDrag();
      else this.endGizmoDrag();
    }) as never);
    tc.addEventListener('objectChange', (() => this.applyGizmoDrag()) as never);
    tc.addEventListener('change', (() => this.requestRender()) as never);
    // r169+ returns a helper object that has to be added to the scene; older versions are the object itself
    const helper = (typeof (tc as unknown as { getHelper?: () => THREE.Object3D }).getHelper === 'function'
      ? (tc as unknown as { getHelper: () => THREE.Object3D }).getHelper()
      : (tc as unknown as THREE.Object3D));
    this.scene.add(helper);
    this.tc = tc;
    this.tcHelper = helper;
    this.applyGizmoAxes();
    this.applySnap();
    this.syncGizmo();
  }

  /** 2D: arrows and planes for X/Y, and only the Z ring for rotation. 3D: everything. */
  private applyGizmoAxes(): void {
    const tc = this.tc;
    if (!tc) return;
    if (this.config.dimension === '3d') {
      tc.showX = tc.showY = tc.showZ = true;
    } else if (this.gizmoMode === 'rotate') {
      tc.showX = false;
      tc.showY = false;
      tc.showZ = true;
    } else {
      tc.showX = true;
      tc.showY = true;
      tc.showZ = false;
    }
  }

  private setSnap(held: boolean): void {
    if (held === this.snapHeld) return;
    this.snapHeld = held;
    this.applySnap();
  }

  private applySnap(): void {
    const tc = this.tc;
    if (!tc) return;
    const g = this.config.gizmo;
    tc.setTranslationSnap(this.snapHeld ? g.snapTranslate : null);
    tc.setRotationSnap(this.snapHeld ? THREE.MathUtils.degToRad(g.snapRotate) : null);
    tc.setScaleSnap(this.snapHeld ? g.snapScale : null);
  }

  /** Is the pointer over a gizmo handle? (TransformControls only updates its hover state on pointer moves.) */
  private gizmoHovered(e: PointerEvent): boolean {
    const tc = this.tc;
    if (!tc || !tc.object) return false;
    const r = this.canvas.getBoundingClientRect();
    try {
      (tc as unknown as { pointerHover: (p: { x: number; y: number; button: number }) => void }).pointerHover({
        x: ((e.clientX - r.left) / r.width) * 2 - 1,
        y: (-(e.clientY - r.top) / r.height) * 2 + 1,
        button: e.button,
      });
    } catch {
      /* hover state from the last pointer move is used */
    }
    return !!tc.axis;
  }

  /** Attaches the gizmo to the selection (or detaches it) and keeps the pivot at the selection center. */
  private syncGizmo(): void {
    const tc = this.tc;
    if (!tc) return;
    const ids = [...this.selNodes].filter((id) => this.nodeInfo.has(id));
    const eligible = this.tool === 'select' && ids.length > 0 && (this.gizmoMode === 'translate' || ids.length >= 2);
    if (!eligible) {
      if (tc.object) tc.detach();
      return;
    }
    if (!this.gizmoDragging) {
      let x = 0, y = 0, z = 0;
      for (const id of ids) {
        const p = this.nodeInfo.get(id)!.body.pos;
        x += p[0];
        y += p[1];
        z += p[2];
      }
      this.pivot.position.set(x / ids.length, y / ids.length, z / ids.length);
      this.pivot.quaternion.identity();
      this.pivot.scale.set(1, 1, 1);
      this.pivot.updateMatrixWorld(true);
    }
    if (tc.object !== this.pivot) tc.attach(this.pivot);
  }

  private beginGizmoDrag(): void {
    const ids = [...this.selNodes].filter((id) => this.nodeInfo.has(id));
    const nodes = new Map<string, Vec3>();
    for (const id of ids) {
      const p = this.nodeInfo.get(id)!.body.pos;
      nodes.set(id, [p[0], p[1], p[2]]);
    }
    this.gizmoStart = { pivot: this.pivot.position.clone(), nodes };
    this.gizmoDragging = true;
    this.dragIds = ids;
    this.events.emit('nodedragstart', { ids });
  }

  private applyGizmoDrag(): void {
    const start = this.gizmoStart;
    const tc = this.tc;
    if (!start || !tc || !this.gizmoDragging) return;
    const dim3 = this.config.dimension === '3d';
    const P0 = start.pivot;
    const mode = tc.mode;
    const d = this.pivot.position;
    const entries: [string, Vec3][] = [];
    const rel = new THREE.Vector3();
    for (const [id, s] of start.nodes) {
      const n = this._graph.getNode(id);
      if (!n) continue;
      let p: Vec3;
      if (mode === 'translate') {
        p = [s[0] + d.x - P0.x, s[1] + d.y - P0.y, s[2] + d.z - P0.z];
      } else {
        rel.set(s[0] - P0.x, s[1] - P0.y, s[2] - P0.z);
        if (mode === 'rotate') rel.applyQuaternion(this.pivot.quaternion);
        else rel.multiply(this.pivot.scale);
        p = [P0.x + rel.x, P0.y + rel.y, P0.z + rel.z];
      }
      entries.push([id, [p[0], p[1], dim3 ? p[2] : n.z ?? 0]]);
    }
    this._graph.setPositions(entries);
  }

  private endGizmoDrag(): void {
    const ids = this.dragIds;
    this.gizmoDragging = false;
    this.gizmoStart = null;
    this.dragIds = [];
    for (const id of ids) this.sim?.unpin(id, !!this._graph.getNode(id)?.pinned);
    this.syncGizmo();
    this.events.emit('nodedragend', { ids });
    this.requestRender();
  }

  // ------------------------------------------------------------------ groups: legend, selection, visibility

  /** The node groups in order of first appearance; `name` is null for nodes without a group. */
  getGroups(): { name: string | null; count: number; color: string; visible: boolean }[] {
    return this.groupList().map((g) => ({ name: g.key === NO_GROUP ? null : g.key, count: g.ids.length, color: g.color, visible: !this.hiddenGroups.has(g.key) }));
  }

  /** Selects all visible nodes of a group (null: nodes without a group). With `additive` the group is added or, if already selected, removed. */
  selectGroup(group: string | null, additive = false): void {
    const key = group ?? NO_GROUP;
    this.searchActive = false;
    if (this.hiddenGroups.has(key)) return;
    const ids = this._graph.nodes.filter((n) => (n.group ?? NO_GROUP) === key).map((n) => n.id);
    const current = new Set(this.selNodes);
    const allIn = ids.length > 0 && ids.every((id) => current.has(id));
    if (additive) {
      for (const id of ids) {
        if (allIn) current.delete(id);
        else current.add(id);
      }
      this.setSelection({ nodes: [...current] });
    } else if (allIn && current.size === ids.length) this.setSelection({});
    else this.setSelection({ nodes: ids });
  }

  setGroupVisible(group: string | null, visible: boolean): void {
    const key = group ?? NO_GROUP;
    if (visible !== this.hiddenGroups.has(key)) return;
    if (visible) this.hiddenGroups.delete(key);
    else this.hiddenGroups.add(key);
    this.dirtyStructure = true;
    this.requestRender();
    this.events.emit('groupvisibility', { hidden: [...this.hiddenGroups].map((k) => (k === NO_GROUP ? null : k)) });
  }

  private groupList(): { key: string; name: string; ids: string[]; color: string }[] {
    const g = this._graph;
    const idx = buildGroupIndex(g);
    const map = new Map<string, { key: string; name: string; ids: string[]; first: NodeData }>();
    for (const n of g.nodes) {
      const key = n.group ?? NO_GROUP;
      let e = map.get(key);
      if (!e) {
        e = { key, name: n.group ?? 'No group', ids: [], first: n };
        map.set(key, e);
      }
      e.ids.push(n.id);
    }
    const list = [...map.values()];
    list.sort((a, b) => (a.key === NO_GROUP ? 1 : 0) - (b.key === NO_GROUP ? 1 : 0));
    return list.map((e) => ({ key: e.key, name: e.name, ids: e.ids, color: resolveNodeStyle(e.first, this.config, idx).color }));
  }

  private updateLegend(): void {
    this.legendEl?.remove();
    this.legendEl = null;
    this.legendRows = [];
    if (!this.config.ui.legend) return;
    const groups = this.groupList();
    if (groups.length < 2) return;
    const box = document.createElement('div');
    box.className = 'gs-legend gs-ui';
    const head = document.createElement('button');
    head.type = 'button';
    head.className = 'gs-legend-head';
    const list = document.createElement('div');
    list.className = 'gs-legend-list';
    const setCollapsed = (c: boolean): void => {
      this.legendCollapsed = c;
      list.hidden = c;
      head.textContent = `${c ? '\u25b8' : '\u25be'} Groups (${groups.length})`;
      head.setAttribute('aria-expanded', String(!c));
    };
    head.addEventListener('click', () => setCollapsed(!this.legendCollapsed));
    for (const g of groups) {
      const item = document.createElement('div');
      item.className = 'gs-legend-item';
      const hidden = this.hiddenGroups.has(g.key);
      const row = document.createElement('button');
      row.type = 'button';
      row.className = 'gs-legend-row' + (hidden ? ' gs-off' : '');
      row.title = hidden ? `${g.name} is hidden` : `Select ${g.name} (Shift+click adds)`;
      const dot = document.createElement('i');
      dot.style.background = g.color;
      const name = document.createElement('span');
      name.className = 'gs-legend-name';
      name.textContent = g.name;
      const count = document.createElement('span');
      count.className = 'gs-legend-count';
      count.textContent = String(g.ids.length);
      row.append(dot, name, count);
      row.addEventListener('click', (e) => this.selectGroup(g.key === NO_GROUP ? null : g.key, e.shiftKey || e.ctrlKey || e.metaKey));
      const eye = document.createElement('button');
      eye.type = 'button';
      eye.className = 'gs-legend-eye';
      const open = 'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM12 15a3 3 0 100-6 3 3 0 000 6z';
      const shut = 'M3 3l18 18M10.6 6.2A9.6 9.6 0 0112 6c6 0 10 6 10 6a17 17 0 01-3.2 3.7M6.6 7.6A17 17 0 002 12s4 7 10 7a9.4 9.4 0 004.4-1.1';
      eye.innerHTML = `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${hidden ? shut : open}"/></svg>`;
      const label = hidden ? `Show ${g.name}` : `Hide ${g.name}`;
      eye.title = label;
      eye.setAttribute('aria-label', label);
      eye.addEventListener('click', () => this.setGroupVisible(g.key === NO_GROUP ? null : g.key, hidden));
      item.append(row, eye);
      list.appendChild(item);
      this.legendRows.push({ key: g.key, ids: g.ids, row });
    }
    box.append(head, list);
    setCollapsed(this.legendCollapsed);
    this.root.appendChild(box);
    this.legendEl = box;
    this.updateLegendSelection();
  }

  /** Marks the groups whose nodes are all selected. */
  private updateLegendSelection(): void {
    for (const r of this.legendRows) {
      const on = !this.hiddenGroups.has(r.key) && r.ids.length > 0 && r.ids.every((id) => this.selNodes.has(id));
      r.row.classList.toggle('gs-on', on);
      r.row.setAttribute('aria-pressed', String(on));
    }
  }

  // ------------------------------------------------------------------ performance overlay and benchmark

  setStatsVisible(visible: boolean): void {
    this.setConfig({ ui: { stats: visible } });
  }

  toggleStats(): void {
    this.setStatsVisible(!this.config.ui.stats);
  }

  private buildStats(): void {
    window.clearInterval(this.statsTimer);
    this.statsEl?.remove();
    this.statsEl = this.statsText = null;
    if (!this.config.ui.stats) return;
    const box = document.createElement('div');
    box.className = 'gs-stats gs-ui';
    const pre = document.createElement('pre');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'gs-btn';
    btn.textContent = 'Run benchmark';
    btn.title = 'Moves the camera for a few seconds, first alone, then together with position updates every frame';
    btn.addEventListener('click', () => {
      btn.disabled = true;
      this.benchText = 'benchmark running ...';
      void this.runBenchmark(4).then((r) => {
        const f = (p: BenchPhase): string => `${p.fps.toFixed(0)} fps (display capped), frame ${p.frameMsAvg.toFixed(1)} avg / ${p.frameMsP95.toFixed(1)} p95 / ${p.frameMsMax.toFixed(1)} max ms, CPU update ${p.updateMsAvg.toFixed(2)} + render ${p.renderMsAvg.toFixed(2)} ms`;
        this.benchText = `camera only:  ${f(r.camera)}\nwith updates: ${f(r.updates)}`;
        btn.disabled = false;
      });
    });
    box.append(pre, btn);
    this.root.appendChild(box);
    this.statsEl = box;
    this.statsText = pre;
    this.statsTimer = window.setInterval(() => this.renderStats(), 500);
    this.renderStats();
  }

  private renderStats(): void {
    const el = this.statsText;
    if (!el) return;
    const p = this.perf;
    const n = Math.min(p.n, 120);
    let upd = 0;
    let rnd = 0;
    let max = 0;
    for (let i = 0; i < n; i++) {
      upd += p.update[i];
      rnd += p.render[i];
      max = Math.max(max, p.update[i] + p.render[i]);
    }
    const now = performance.now();
    const live = p.stamps.length > 0 && now - p.stamps[p.stamps.length - 1] < 600;
    const info = this.renderer.info;
    if (this.gpuName === null) {
      const gl = this.renderer.getContext();
      const ext = gl.getExtension('WEBGL_debug_renderer_info');
      this.gpuName = ext ? String(gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)) : 'unknown';
    }
    const fmt = (x: number): string => x.toFixed(x < 10 ? 2 : 1);
    const lines = [
      live ? `${p.stamps.length} fps` : 'idle (draws only when something changes)',
      `CPU per frame  ${fmt(n ? (upd + rnd) / n : 0)} ms avg, ${fmt(max)} max`,
      `  update ${fmt(n ? upd / n : 0)}   render ${fmt(n ? rnd / n : 0)}`,
      `draw calls ${info.render.calls}   triangles ${info.render.triangles.toLocaleString()}`,
      `nodes ${this.nodeInfo.size}   edges ${this.edgeInfo.size}   geometries ${info.memory.geometries}   textures ${info.memory.textures}`,
      `layout ${this.sim ? `running, step ${fmt(p.stepMs)} ms, alpha ${this.sim.alpha.toFixed(2)}` : 'idle'}`,
      `last rebuild ${fmt(p.rebuildMs)} ms   last position update ${fmt(p.positionsMs)} ms`,
      `GPU ${this.gpuName}`,
    ];
    if (this.benchText) lines.push('', this.benchText);
    el.textContent = lines.join('\n');
  }

  /**
   * Moves the camera for `seconds` (half of it alone, half together with position updates every frame, which is what a
   * running layout costs) and reports frame times. The browser caps fps at the refresh rate; compare the CPU times.
   */
  async runBenchmark(seconds = 4): Promise<BenchmarkResult> {
    if (this.benchmarking) throw new Error('A benchmark is already running');
    this.benchmarking = true;
    this.stopLayout();
    const cam = this.camera;
    const saved = { pos: cam.position.clone(), zoom: this.ortho.zoom, target: this.controls.target.clone() };
    try {
      const camera = await this.benchPhase((seconds * 1000) / 2, false);
      const updates = await this.benchPhase((seconds * 1000) / 2, true);
      return { camera, updates };
    } finally {
      cam.position.copy(saved.pos);
      this.ortho.zoom = saved.zoom;
      this.ortho.updateProjectionMatrix();
      this.controls.target.copy(saved.target);
      this.controls.update();
      this.benchmarking = false;
      this.requestRender();
    }
  }

  private benchPhase(ms: number, forceUpdates: boolean): Promise<BenchPhase> {
    return new Promise((resolve) => {
      const dts: number[] = [];
      const upd: number[] = [];
      const rnd: number[] = [];
      const baseZoom = this.ortho.zoom;
      const start = performance.now();
      let last = 0;
      let angle = 0;
      const done = (): void => {
        const sorted = [...dts].sort((a, b) => a - b);
        const avg = (a: number[]): number => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);
        const frameAvg = avg(dts);
        resolve({
          frames: dts.length,
          fps: frameAvg ? 1000 / frameAvg : 0,
          frameMsAvg: frameAvg,
          frameMsP95: sorted.length ? sorted[Math.floor(sorted.length * 0.95)] : 0,
          frameMsMax: sorted.length ? sorted[sorted.length - 1] : 0,
          updateMsAvg: avg(upd),
          renderMsAvg: avg(rnd),
        });
      };
      const tick = (ts: number): void => {
        if (this.disposed) return done();
        if (last) dts.push(ts - last);
        last = ts;
        angle += 0.04;
        if (this.config.dimension === '2d') {
          this.ortho.zoom = baseZoom * (1 + 0.15 * Math.sin(angle));
          this.ortho.updateProjectionMatrix();
        } else {
          const off = this.tmpV.copy(this.persp.position).sub(this.controls.target);
          off.applyAxisAngle(Y_AXIS, 0.02);
          this.persp.position.copy(this.controls.target).add(off);
        }
        this.dirtyLabels = true;
        if (forceUpdates) this.dirtyPositions = true;
        this.frame();
        const i = (this.perf.n - 1) % 120;
        upd.push(this.perf.update[i]);
        rnd.push(this.perf.render[i]);
        if (performance.now() - start < ms) requestAnimationFrame(tick);
        else done();
      };
      requestAnimationFrame(tick);
    });
  }

  // ------------------------------------------------------------------ search and help

  /**
   * Finds nodes (see `search` in the configuration for the syntax) and, by default, selects them.
   * Returns the matches; terms shorter than `search.minChars` are ignored.
   */
  search(query: string, opts: { select?: boolean; fit?: boolean } = {}): SearchResult {
    if (!this.searchIndex) this.searchIndex = new NodeSearchIndex(this._graph);
    const res = this.searchIndex.search(query, { fields: this.config.search.fields, minChars: this.config.search.minChars });
    if (opts.select ?? true) {
      if (res.ids.length || (res.query.trim() !== '' && !res.tooShort)) {
        this.searchActive = true;
        this.setSelection({ nodes: res.ids });
      } else if (this.searchActive) {
        this.searchActive = false; // text deleted or too short: drop what the search selected
        this.setSelection({});
      }
    }
    if (opts.fit && res.ids.length) this.fit(res.ids);
    this.events.emit('search', { query, ids: res.ids, tooShort: res.tooShort });
    return res;
  }

  /** Clears the search box and the selection it made. */
  clearSearch(): void {
    this.searchText = '';
    if (this.searchInput) this.searchInput.value = '';
    this.search('');
    if (this.searchCount) this.searchCount.textContent = '';
  }

  /** Puts the cursor into the search box (the editor binds this to Ctrl+F). */
  focusSearch(): void {
    this.searchInput?.focus();
    this.searchInput?.select();
  }

  private buildSearch(): void {
    this.searchEl?.remove();
    this.searchEl = this.searchInput = this.searchCount = null;
    if (!this.config.ui.search) return;
    const box = document.createElement('div');
    box.className = 'gs-search gs-ui';
    box.setAttribute('role', 'search');
    box.innerHTML = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="M15.5 15.5L21 21"/></svg>';
    const input = document.createElement('input');
    input.type = 'text';
    input.placeholder = 'Search\u2026';
    input.setAttribute('aria-label', 'Search nodes and groups');
    input.title = `Find nodes while you type. group:Sales, tag:x, id:n1 search one field. Enter zooms to the matches, Esc clears.`;
    input.autocomplete = 'off';
    input.spellcheck = false;
    input.value = this.searchText;
    const count = document.createElement('span');
    count.className = 'gs-search-count';
    count.setAttribute('aria-live', 'polite');
    const clear = document.createElement('button');
    clear.type = 'button';
    clear.className = 'gs-search-clear';
    clear.textContent = '\u00d7';
    clear.title = 'Clear search';
    clear.setAttribute('aria-label', 'Clear search');
    const run = (fit: boolean): void => {
      this.searchText = input.value;
      const r = this.search(input.value, { fit });
      const min = this.config.search.minChars;
      count.textContent = r.ids.length ? `${r.ids.length} found` : r.tooShort ? `${min}+ characters` : input.value.trim() ? 'No match' : '';
      clear.hidden = input.value === '';
    };
    input.addEventListener('input', () => run(false));
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        run(this.config.search.fitOnEnter);
      } else if (e.key === 'Escape') {
        e.stopPropagation();
        this.clearSearch();
        clear.hidden = true;
        input.blur();
      }
    });
    clear.addEventListener('click', () => {
      this.clearSearch();
      clear.hidden = true;
      input.focus();
    });
    clear.hidden = input.value === '';
    box.append(input, count, clear);
    this.root.appendChild(box);
    this.searchEl = box;
    this.searchInput = input;
    this.searchCount = count;
  }

  toggleHelp(): void {
    if (this.helpEl) this.closeHelp();
    else this.openHelp();
  }

  private openHelp(): void {
    this.closeHelp();
    const mac = typeof navigator !== 'undefined' && /mac|iphone|ipad/i.test(navigator.platform || navigator.userAgent);
    const box = document.createElement('div');
    box.className = 'gs-help gs-ui';
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-label', 'Controls');
    const title = document.createElement('div');
    title.className = 'gs-help-title';
    title.textContent = 'Controls';
    box.appendChild(title);
    for (const l of helpLines(this.config, mac)) {
      const row = document.createElement('div');
      row.className = 'gs-help-row';
      const k = document.createElement('b');
      k.textContent = l.keys;
      const t = document.createElement('span');
      t.textContent = l.text;
      row.append(k, t);
      box.appendChild(row);
    }
    this.root.appendChild(box);
    this.helpEl = box;
    this.helpButton?.setAttribute('aria-expanded', 'true');
  }

  private closeHelp(): void {
    this.helpEl?.remove();
    this.helpEl = null;
    this.helpButton?.setAttribute('aria-expanded', 'false');
  }

  // ------------------------------------------------------------------ picking

  private ndc = new THREE.Vector2();

  private eventPoint(e: MouseEvent): { x: number; y: number } {
    const r = this.canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  /** World position of a screen point on the plane through `anchor` that faces the camera. */
  private worldAt(sx: number, sy: number, anchor: Vec3): Vec3 | null {
    this.camera.updateMatrixWorld();
    this.ndc.set((sx / this.width) * 2 - 1, -(sy / this.height) * 2 + 1);
    this.raycaster.setFromCamera(this.ndc, this.camera);
    const dir = this.camera.getWorldDirection(this.tmpV2);
    this.plane.setFromNormalAndCoplanarPoint(dir, this.tmpV.set(anchor[0], anchor[1], anchor[2]));
    const hit = this.raycaster.ray.intersectPlane(this.plane, this.tmpS);
    return hit ? [hit.x, hit.y, hit.z] : null;
  }

  private pick(sx: number, sy: number): Hit {
    this.camera.updateMatrixWorld();
    const dim3 = this.config.dimension === '3d';
    const v = this.tmpV;
    let best: string | null = null;
    let bestZ = Infinity;
    for (const [id, info] of this.nodeInfo) {
      const p = info.body.pos;
      v.set(p[0], p[1], p[2]).project(this.camera);
      if (v.z < -1 || v.z > 1) continue;
      const px = (v.x * 0.5 + 0.5) * this.width;
      const py = (-v.y * 0.5 + 0.5) * this.height;
      const ppu = this.pxPerUnitAt(p[0], p[1], p[2]);
      const dx = (sx - px) / Math.max(info.body.hw * ppu, 4);
      const dy = (sy - py) / Math.max(info.body.hh * ppu, 4);
      const inside = info.body.ellipse || dim3 ? dx * dx + dy * dy <= 1 : Math.abs(dx) <= 1 && Math.abs(dy) <= 1;
      if (inside && v.z <= bestZ) {
        best = id;
        bestZ = v.z;
      }
    }
    if (best) return { kind: 'node', id: best };
    if (this.edgeInfo.size > this.config.interaction.pickLimit) return { kind: null, id: null };
    let bestEdge: string | null = null;
    let bestD = 6;
    for (const [id, info] of this.edgeInfo) {
      const pts = info.path;
      if (pts.length < 2) continue;
      let ax = 0;
      let ay = 0;
      for (let i = 0; i < pts.length; i++) {
        v.set(pts[i][0], pts[i][1], pts[i][2]).project(this.camera);
        const bx = (v.x * 0.5 + 0.5) * this.width;
        const by = (-v.y * 0.5 + 0.5) * this.height;
        if (i > 0) {
          const d = geometry.distToSegment(sx, sy, ax, ay, bx, by);
          if (d < bestD) {
            bestD = d;
            bestEdge = id;
          }
        }
        ax = bx;
        ay = by;
      }
    }
    return bestEdge ? { kind: 'edge', id: bestEdge } : { kind: null, id: null };
  }

  // ------------------------------------------------------------------ pointer interaction

  private onWheel = (): void => {
    this.activeUntil = performance.now() + 700;
    this.requestRender();
  };

  private onPointerDown = (e: PointerEvent): void => {
    if (this.helpEl && !(e.target as Element).closest?.('.gs-help, .gs-help-btn')) this.closeHelp();
    if ((e.target as Element).closest?.('.gs-ui')) return;
    this.pointerIsDown = true;
    this.requestRender();
    if (this.gizmoHovered(e)) return; // the gizmo handles this press itself
    if (e.button !== 0) return;
    const p = this.eventPoint(e);
    this.lastPointer = p;
    const hit = this.pick(p.x, p.y);
    const additive = e.shiftKey;
    const inter = this.config.interaction;
    const wasSelected = hit.kind === 'node' && this.selNodes.has(hit.id);
    this.down = { x: p.x, y: p.y, hit, additive, wasSelected, moved: false, button: e.button };
    this.hideTooltip();
    if (hit.kind === 'node') {
      if (this.tool === 'connect') {
        this.drag = { type: 'connect', from: hit.id };
      } else {
        if (inter.select && !wasSelected) {
          if (additive && inter.multiSelect) this.selNodes.add(hit.id);
          else {
            this.selNodes = new Set([hit.id]);
            this.selEdges.clear();
          }
          this.dirtyNodes = this.dirtyEdges = true;
          this.events.emit('selection', this.getSelection());
          this.requestRender();
        }
        if (inter.dragNodes) {
          const ids = this.selNodes.has(hit.id) ? [...this.selNodes] : [hit.id];
          const anchor = this.nodeInfo.get(hit.id)!.body.pos;
          const w = this.worldAt(p.x, p.y, anchor);
          if (w) {
            const offsets = new Map<string, Vec3>();
            const starts = new Map<string, Vec3>();
            for (const id of ids) {
              const b = this.nodeInfo.get(id)?.body.pos;
              if (b) {
                offsets.set(id, [b[0] - w[0], b[1] - w[1], b[2] - w[2]]);
                starts.set(id, [b[0], b[1], b[2]]);
              }
            }
            this.drag = { type: 'nodes', ids, primary: hit.id, offsets, starts, anchor: [anchor[0], anchor[1], anchor[2]], px: p.x, py: p.y, moved: false };
          }
        }
      }
    } else if (e.shiftKey && inter.select && inter.multiSelect) {
      this.drag = { type: 'box', x0: p.x, y0: p.y };
    }
    if (this.drag) {
      this.controls.enabled = false;
      this.canvas.setPointerCapture(e.pointerId);
    }
  };

  private onPointerMove = (e: PointerEvent): void => {
    const p = this.eventPoint(e);
    this.lastPointer = p;
    const down = this.down;
    if (down && !down.moved && Math.hypot(p.x - down.x, p.y - down.y) > DRAG_THRESHOLD) down.moved = true;
    const d = this.drag;
    if (!d) {
      if (!down && !(this.tc?.object && this.tc.axis)) this.scheduleHover();
      this.moveTooltip(p);
      return;
    }
    if (d.type === 'nodes') {
      if (!down?.moved) return;
      if (!d.moved) {
        d.moved = true;
        this.dragIds = d.ids;
        this.canvas.style.cursor = 'grabbing';
        this.events.emit('nodedragstart', { ids: d.ids });
      }
      this.dragNodes(d, p);
    } else if (d.type === 'connect') {
      this.updateRubber(d.from, p);
      const hit = this.pick(p.x, p.y);
      const hn = hit.kind === 'node' ? hit.id : null;
      if (hn !== this.hoverNode) {
        this.hoverNode = hn;
        this.dirtyNodes = true;
        this.requestRender();
      }
    } else if (down?.moved) {
      const x = Math.min(d.x0, p.x);
      const y = Math.min(d.y0, p.y);
      this.boxEl.hidden = false;
      Object.assign(this.boxEl.style, { left: `${x}px`, top: `${y}px`, width: `${Math.abs(p.x - d.x0)}px`, height: `${Math.abs(p.y - d.y0)}px` });
    }
  };

  private onPointerUp = (e: PointerEvent): void => {
    this.pointerIsDown = false;
    this.activeUntil = performance.now() + 1000;
    this.requestRender();
    const down = this.down;
    const drag = this.drag;
    this.down = null;
    this.drag = null;
    this.controls.enabled = true;
    if (this.canvas.hasPointerCapture?.(e.pointerId)) this.canvas.releasePointerCapture(e.pointerId);
    this.boxEl.hidden = true;
    this.removeRubber();
    this.setAxisGuide(null);
    this.canvas.style.cursor = this.tool === 'connect' ? 'crosshair' : '';
    if (drag?.type === 'nodes' && drag.moved) {
      for (const id of drag.ids) this.sim?.unpin(id, !!this._graph.getNode(id)?.pinned);
      this.dragIds = [];
      this.events.emit('nodedragend', { ids: drag.ids });
      return;
    }
    if (!down || e.type === 'pointercancel') return;
    const p = this.eventPoint(e);
    if (drag?.type === 'connect') {
      const hit = this.pick(p.x, p.y);
      if (hit.kind === 'node') this.events.emit('connect', { source: drag.from, target: hit.id });
      return;
    }
    if (drag?.type === 'box' && down.moved) {
      this.selectInBox(drag.x0, drag.y0, p.x, p.y, down.additive);
      return;
    }
    if (down.moved) return; // camera pan / orbit
    this.handleClick(down.hit, down.additive, down.wasSelected, e);
  };

  private handleClick(hit: Hit, additive: boolean, wasSelected: boolean, e: PointerEvent): void {
    const inter = this.config.interaction;
    const openOn = (mod: boolean): boolean => inter.openLinks === 'click' || (inter.openLinks === 'ctrl-click' && mod);
    const mod = e.ctrlKey || e.metaKey;
    if (hit.kind === 'node') {
      const node = this._graph.getNode(hit.id);
      if (!node) return;
      if (inter.select && wasSelected) {
        if (additive) this.selNodes.delete(hit.id);
        else if (this.selNodes.size > 1) this.selNodes = new Set([hit.id]);
        this.dirtyNodes = this.dirtyEdges = true;
        this.events.emit('selection', this.getSelection());
        this.requestRender();
      }
      this.events.emit('nodeclick', { id: hit.id, node, originalEvent: e });
      if (openOn(mod)) this.openLink('node', hit.id);
    } else if (hit.kind === 'edge') {
      const edge = this._graph.getEdge(hit.id);
      if (!edge) return;
      if (inter.select) {
        if (additive && inter.multiSelect) {
          if (!this.selEdges.delete(hit.id)) this.selEdges.add(hit.id);
        } else {
          this.selNodes.clear();
          this.selEdges = new Set([hit.id]);
        }
        this.dirtyNodes = this.dirtyEdges = true;
        this.events.emit('selection', this.getSelection());
        this.requestRender();
      }
      this.events.emit('edgeclick', { id: hit.id, edge, originalEvent: e });
      if (openOn(mod)) this.openLink('edge', hit.id);
    } else {
      if (!additive) this.clearSelection();
      const p = this.eventPoint(e);
      const position = this.worldAt(p.x, p.y, this.config.dimension === '3d' ? (this.controls.target.toArray() as Vec3) : [0, 0, 0]) ?? [0, 0, 0];
      this.events.emit('backgroundclick', { position, originalEvent: e });
    }
  }

  private onDblClick = (e: MouseEvent): void => {
    if ((e.target as Element).closest?.('.gs-ui')) return;
    const p = this.eventPoint(e);
    const hit = this.pick(p.x, p.y);
    const dbl = this.config.interaction.openLinks === 'dblclick';
    if (hit.kind === 'node') {
      const node = this._graph.getNode(hit.id);
      if (node) this.events.emit('nodedblclick', { id: hit.id, node, originalEvent: e });
      if (dbl) this.openLink('node', hit.id);
    } else if (hit.kind === 'edge') {
      if (dbl) this.openLink('edge', hit.id);
    } else {
      const position = this.worldAt(p.x, p.y, this.config.dimension === '3d' ? (this.controls.target.toArray() as Vec3) : [0, 0, 0]) ?? [0, 0, 0];
      this.events.emit('backgrounddblclick', { position, originalEvent: e });
    }
  };

  private onPointerLeave = (): void => {
    this.pointerInside = false;
    if (this.drag) return;
    this.hideTooltip();
    if (this.hoverNode || this.hoverEdge) {
      this.hoverNode = this.hoverEdge = null;
      this.dirtyNodes = this.dirtyEdges = true;
      this.events.emit('hover', { kind: null, id: null });
      this.requestRender();
    }
  };

  /** Axes currently locked by the X / Y / Z keys (Z only exists in 3D). */
  private activeAxes(): Axis[] {
    if (!this.config.interaction.axisLock) return [];
    const dim3 = this.config.dimension === '3d';
    return [...this.axisKeys].filter((a) => dim3 || a !== 'z');
  }

  private toScreen(p: Vec3): { x: number; y: number } {
    this.camera.updateMatrixWorld();
    this.tmpV.set(p[0], p[1], p[2]).project(this.camera);
    return { x: (this.tmpV.x * 0.5 + 0.5) * this.width, y: (-this.tmpV.y * 0.5 + 0.5) * this.height };
  }

  /**
   * Moves the dragged nodes. Without axis keys they follow the pointer. With one held key (X, Y or Z) they move only
   * along that axis, measured by projecting the pointer motion onto the axis as it appears on screen. With two keys they
   * move within that plane.
   */
  private dragNodes(d: Extract<Drag, { type: 'nodes' }>, p: { x: number; y: number }): void {
    const dim3 = this.config.dimension === '3d';
    const axes = this.activeAxes();
    const entries: [string, Vec3][] = [];
    let guide: { origin: Vec3; axis: Axis } | null = null;
    if (axes.length === 1) {
      const axis = axes[0];
      const origin = d.starts.get(d.primary);
      if (!origin) return;
      const unit: Vec3 = [0, 0, 0];
      unit[AXIS_INDEX[axis]] = 1;
      const L = 10;
      const s0 = this.toScreen(origin);
      const s1 = this.toScreen([origin[0] + unit[0] * L, origin[1] + unit[1] * L, origin[2] + unit[2] * L]);
      const sx = s1.x - s0.x;
      const sy = s1.y - s0.y;
      const dd = sx * sx + sy * sy;
      const t = dd > 1e-6 ? (((p.x - d.px) * sx + (p.y - d.py) * sy) / dd) * L : 0;
      for (const id of d.ids) {
        const st = d.starts.get(id);
        const n = this._graph.getNode(id);
        if (!st || !n) continue;
        entries.push([id, [st[0] + unit[0] * t, st[1] + unit[1] * t, dim3 ? st[2] + unit[2] * t : n.z ?? 0]]);
      }
      guide = { origin, axis };
    } else {
      const w = this.worldAt(p.x, p.y, d.anchor);
      if (!w) return;
      const free = axes.length === 0;
      for (const id of d.ids) {
        const off = d.offsets.get(id);
        const st = d.starts.get(id);
        const n = this._graph.getNode(id);
        if (!off || !st || !n) continue;
        const pick = (i: number, axis: Axis): number => (free || axes.includes(axis) ? w[i] + off[i] : st[i]);
        entries.push([id, [pick(0, 'x'), pick(1, 'y'), dim3 ? pick(2, 'z') : n.z ?? 0]]);
      }
    }
    this.setAxisGuide(guide);
    this._graph.setPositions(entries);
  }

  private setAxisGuide(g: { origin: Vec3; axis: Axis } | null): void {
    if (!g) {
      if (!this.guide) return;
      this.scene.remove(this.guide);
      this.guide.geometry.dispose();
      (this.guide.material as THREE.Material).dispose();
      this.guide = null;
      this.requestRender();
      return;
    }
    if (!this.guide) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
      this.guide = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: this.color(AXIS_COLOR[g.axis]), depthTest: false, transparent: true, opacity: 0.8 }));
      this.guide.renderOrder = 19;
      this.guide.frustumCulled = false;
      this.scene.add(this.guide);
    }
    (this.guide.material as THREE.LineBasicMaterial).color.copy(this.color(AXIS_COLOR[g.axis]));
    const a = this.guide.geometry.getAttribute('position') as THREE.BufferAttribute;
    const i = AXIS_INDEX[g.axis];
    const lo: Vec3 = [g.origin[0], g.origin[1], g.origin[2]];
    const hi: Vec3 = [g.origin[0], g.origin[1], g.origin[2]];
    lo[i] -= 50000;
    hi[i] += 50000;
    a.setXYZ(0, lo[0], lo[1], lo[2]);
    a.setXYZ(1, hi[0], hi[1], hi[2]);
    a.needsUpdate = true;
    this.requestRender();
  }

  private onKeyDown = (e: KeyboardEvent): void => {
    this.setSnap(e.ctrlKey || e.metaKey);
    const typing = !!(e.target as HTMLElement | null)?.matches?.('input, textarea, select');
    if (e.key === 'Escape' && this.helpEl) this.closeHelp();
    if (e.key === '?' && this.pointerInside && !typing && this.config.ui.help) {
      e.preventDefault();
      this.toggleHelp();
    }
    if (e.key === 'Escape' && this.container.classList.contains('gs-pseudo-fullscreen')) void this.toggleFullscreen(false);
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    const t = e.target as HTMLElement | null;
    if (t?.matches?.('input, textarea, select')) return;
    const k = e.key.toLowerCase();
    if ((k === 'x' || k === 'y' || k === 'z') && !this.axisKeys.has(k)) {
      this.axisKeys.add(k);
      this.refreshAxisDrag();
    }
  };

  private onKeyUp = (e: KeyboardEvent): void => {
    this.setSnap(e.ctrlKey || e.metaKey);
    const k = e.key.toLowerCase();
    if ((k === 'x' || k === 'y' || k === 'z') && this.axisKeys.delete(k)) this.refreshAxisDrag();
  };

  private onBlur = (): void => {
    if (this.axisKeys.size) {
      this.axisKeys.clear();
      this.refreshAxisDrag();
    }
  };

  /** Re-applies the running node drag after a key press or release so the constraint takes effect immediately. */
  private refreshAxisDrag(): void {
    const d = this.drag;
    if (d?.type === 'nodes' && d.moved) this.dragNodes(d, this.lastPointer);
  }

  private selectInBox(x0: number, y0: number, x1: number, y1: number, additive: boolean): void {
    this.camera.updateMatrixWorld();
    const minX = Math.min(x0, x1), maxX = Math.max(x0, x1), minY = Math.min(y0, y1), maxY = Math.max(y0, y1);
    const ids = additive ? new Set(this.selNodes) : new Set<string>();
    for (const [id, info] of this.nodeInfo) {
      const p = info.body.pos;
      this.tmpV.set(p[0], p[1], p[2]).project(this.camera);
      const px = (this.tmpV.x * 0.5 + 0.5) * this.width;
      const py = (-this.tmpV.y * 0.5 + 0.5) * this.height;
      if (this.tmpV.z >= -1 && this.tmpV.z <= 1 && px >= minX && px <= maxX && py >= minY && py <= maxY) ids.add(id);
    }
    this.setSelection({ nodes: [...ids] });
  }

  private scheduleHover(): void {
    if (!this.config.interaction.hover || this.hoverRaf) return;
    this.hoverRaf = requestAnimationFrame(() => {
      this.hoverRaf = 0;
      this.updateHover();
    });
  }

  private updateHover(): void {
    if (this.drag || this.disposed) return;
    const hit = this.pick(this.lastPointer.x, this.lastPointer.y);
    const hn = hit.kind === 'node' ? hit.id : null;
    const he = hit.kind === 'edge' ? hit.id : null;
    if (hn !== this.hoverNode) this.dirtyNodes = true;
    if (he !== this.hoverEdge) this.dirtyEdges = true;
    if (hn !== this.hoverNode || he !== this.hoverEdge) {
      this.hoverNode = hn;
      this.hoverEdge = he;
      this.events.emit('hover', { kind: hit.kind, id: hit.id });
      this.showTooltip(hit);
      this.requestRender();
    }
    const item = hit.kind === 'node' ? this._graph.getNode(hit.id) : hit.kind === 'edge' ? this._graph.getEdge(hit.id) : undefined;
    this.canvas.style.cursor = this.tool === 'connect' ? 'crosshair' : item?.url ? 'pointer' : '';
  }

  // ------------------------------------------------------------------ tooltip, rubber band, link panel

  private hideTooltip(): void {
    this.tooltipEl.hidden = true;
  }

  private showTooltip(hit: Hit): void {
    const el = this.tooltipEl;
    if (!this.config.interaction.tooltip || hit.kind === null) {
      el.hidden = true;
      return;
    }
    el.replaceChildren();
    const line = (text: string, cls?: string): void => {
      const d = document.createElement('div');
      if (cls) d.className = cls;
      d.textContent = text;
      el.appendChild(d);
    };
    const g = this._graph;
    if (hit.kind === 'node') {
      const n = g.getNode(hit.id);
      if (!n) return;
      line(n.label ?? n.id, 'gs-tt-title');
      if (n.sublabel) line(n.sublabel, 'gs-tt-muted');
      if (n.group) line(n.group, 'gs-tt-muted');
      if (n.url) line(n.url, 'gs-tt-muted');
      const nodeHint = this.linkHint(n.url);
      if (nodeHint) line(nodeHint, 'gs-tt-hint');
      for (const [k, v] of Object.entries(n.props ?? {})) line(`${k}: ${v}`, 'gs-tt-muted');
    } else {
      const e = g.getEdge(hit.id);
      if (!e) return;
      const name = (id: string): string => g.getNode(id)?.label ?? id;
      line(`${name(e.source)} ${g.isDirected(e) ? '\u2192' : '\u2014'} ${name(e.target)}`, 'gs-tt-title');
      line(`weight ${g.weightOf(e)}`, 'gs-tt-muted');
      if (e.label) line(e.label);
      if (e.url) line(e.url, 'gs-tt-muted');
      const edgeHint = this.linkHint(e.url);
      if (edgeHint) line(edgeHint, 'gs-tt-hint');
    }
    el.hidden = false;
    this.moveTooltip(this.lastPointer);
  }

  private moveTooltip(p: { x: number; y: number }): void {
    const el = this.tooltipEl;
    if (el.hidden) return;
    const pad = 14;
    let x = p.x + pad;
    let y = p.y + pad;
    if (x + el.offsetWidth > this.width) x = Math.max(0, p.x - el.offsetWidth - pad);
    if (y + el.offsetHeight > this.height) y = Math.max(0, p.y - el.offsetHeight - pad);
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
  }

  private updateRubber(from: string, p: { x: number; y: number }): void {
    const info = this.nodeInfo.get(from);
    if (!info) return;
    const w = this.worldAt(p.x, p.y, info.body.pos) ?? info.body.pos;
    if (!this.rubber) {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
      const m = new THREE.LineBasicMaterial({ color: this.color(this.config.selection.color), depthTest: false, transparent: true });
      this.rubber = new THREE.Line(g, m);
      this.rubber.renderOrder = 20;
      this.rubber.frustumCulled = false;
      this.scene.add(this.rubber);
    }
    const a = this.rubber.geometry.getAttribute('position') as THREE.BufferAttribute;
    a.setXYZ(0, info.body.pos[0], info.body.pos[1], info.body.pos[2]);
    a.setXYZ(1, w[0], w[1], w[2]);
    a.needsUpdate = true;
    this.requestRender();
  }

  private removeRubber(): void {
    if (!this.rubber) return;
    this.scene.remove(this.rubber);
    this.rubber.geometry.dispose();
    (this.rubber.material as THREE.Material).dispose();
    this.rubber = null;
    this.requestRender();
  }

  private openPanel(url: string, title: string): void {
    this.closePanel();
    const panel = document.createElement('div');
    panel.className = 'gs-panel gs-ui';
    const head = document.createElement('div');
    head.className = 'gs-panel-head';
    const t = document.createElement('span');
    t.className = 'gs-panel-title';
    t.textContent = title;
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'gs-btn';
    close.textContent = '\u00d7';
    close.title = 'Close';
    close.setAttribute('aria-label', 'Close panel');
    close.addEventListener('click', () => this.closePanel());
    head.append(t, close);
    const frame = document.createElement('iframe');
    frame.setAttribute('sandbox', this.config.links.panelSandbox);
    frame.title = title;
    frame.src = url;
    panel.append(head, frame);
    this.root.appendChild(panel);
    this.panelEl = panel;
  }
}
